const questions = [
// --- CAP 1: FONDAMENTI ---
{q:"Quale dei seguenti è un tipico obiettivo del testing?", o:["A. Trovare il colpevole dei difetti","B. Prevenire i difetti","C. Riparare i difetti","D. Dimostrare l'assenza di difetti"], a:1, e:"La prevenzione dei difetti è un obiettivo chiave. Ripararli è debugging. Dimostrare l'assenza è impossibile.", c:"1.1 Obiettivi"},
{q:"Quale affermazione descrive meglio la differenza tra testing e debugging?", o:["A. Il testing mostra i fallimenti, il debugging trova la causa radice.","B. Il testing corregge i difetti, il debugging li trova.","C. Il testing è dinamico, il debugging è statico.","D. Non c'è differenza."], a:0, e:"Il testing identifica i guasti (fallimenti), il debugging isola la causa radice e la corregge.", c:"1.1 Testing e Debugging"},
{q:"Perché il testing esaustivo è considerato impossibile?", o:["A. I tester non hanno mai abbastanza tempo.","B. Ci sono troppe combinazioni di input e precondizioni.","C. Gli sviluppatori introducono sempre nuovi bug.","D. Gli strumenti non sono abbastanza veloci."], a:1, e:"A causa dell'elevato numero di combinazioni, percorsi e dati, testare tutto è impossibile tranne in casi banali.", c:"1.3 Sette principi"},
{q:"Cosa si intende per 'Raggruppamento dei difetti' (Defect Clustering)?", o:["A. I difetti appaiono sempre il venerdì.","B. Un piccolo numero di moduli contiene la maggior parte dei difetti.","C. I difetti si raggruppano nei test di regressione.","D. I tester trovano difetti a grappoli."], a:1, e:"Principio 4: la maggior parte dei difetti si concentra in un piccolo numero di moduli complessi o modificati di recente.", c:"1.3 Sette principi"},
{q:"Come viene chiamato il principio per cui ripetere gli stessi test non trova più nuovi difetti?", o:["A. Dipendenza dal contesto.","B. Fallacia dell'assenza di difetti.","C. Paradosso del pesticida.","D. Testing esaustivo."], a:2, e:"Come i parassiti si abituano al pesticida, i bug sfuggono agli stessi test eseguiti ripetutamente. I test vanno aggiornati.", c:"1.3 Sette principi"},
{q:"In quale attività del processo di test si definiscono i 'Criteri di Uscita' (Exit Criteria)?", o:["A. Test Planning","B. Test Monitoring","C. Test Design","D. Test Execution"], a:0, e:"I criteri di uscita e di ingresso sono stabiliti durante la pianificazione (Test Planning).", c:"1.4 Processo di test"},
{q:"Cos'è la 'Test Basis' (Base di test)?", o:["A. Il server su cui girano i test.","B. I documenti e requisiti da cui vengono derivati i casi di test.","C. L'insieme di tutti i tester.","D. Il tool di automazione."], a:1, e:"La test basis è qualsiasi informazione usata come base per analizzare e progettare i test (es. specifiche, user stories).", c:"1.4 Processo di test"},
{q:"Cosa si fa durante l'attività di 'Test Implementation'?", o:["A. Si scrivono i requisiti.","B. Si organizzano le procedure di test e si preparano i dati e l'ambiente.","C. Si chiude il progetto.","D. Si analizzano i rischi."], a:1, e:"L'implementazione prende i test case e li trasforma in test procedure, preparando dati, script e ambiente prima dell'esecuzione.", c:"1.4 Processo di test"},
{q:"Dal punto di vista psicologico, qual è il rischio del 'Confirmation Bias' nel testing?", o:["A. Il tester rifiuta di testare.","B. Lo sviluppatore crede inconsciamente che il suo codice sia corretto e fatica a trovarne i difetti.","C. Il cliente conferma sempre i requisiti.","D. Il project manager ignora i tester."], a:1, e:"Il bias di conferma porta le persone a cercare informazioni che confermano le loro convinzioni, rendendo difficile testare il proprio codice oggettivamente.", c:"1.5 Psicologia del testing"},
{q:"Come dovrebbe comunicare un tester i difetti a uno sviluppatore?", o:["A. In modo aggressivo per farsi rispettare.","B. Focalizzandosi sulla persona che ha scritto il codice.","C. In modo costruttivo, fattuale e oggettivo.","D. Di nascosto senza registrarli sul tool."], a:2, e:"La comunicazione deve essere professionale, incentrata sul prodotto e sul miglioramento della qualità, non sulle colpe.", c:"1.5 Psicologia del testing"},

// --- CAP 2: CICLO DI VITA ---
{q:"Nel modello a V, il livello 'Component Testing' cosa verifica?", o:["A. Requisiti di sistema.","B. Design architetturale.","C. Design dettagliato (specifiche dei moduli).","D. Requisiti di business."], a:2, e:"Nel modello a V, il test di componente è la controparte del design di dettaglio.", c:"2.1 Modelli di ciclo di vita"},
{q:"Quale approccio di sviluppo prevede cicli brevi, feedback continuo e testing integrato quotidianamente?", o:["A. Modello a Cascata (Waterfall).","B. Sviluppo Agile.","C. Modello a V.","D. Modello a Spirale lungo."], a:1, e:"L'approccio Agile (es. Scrum) si basa su iterazioni brevi, integrazione continua e testing anticipato (Shift-Left).", c:"2.1 Modelli di ciclo di vita"},
{q:"Cos'è lo 'Shift-Left' testing?", o:["A. Testare solo il lato sinistro della UI.","B. Coinvolgere i tester il più presto possibile nel ciclo di vita dello sviluppo.","C. Spostare tutti i test in fase di produzione.","D. Assumere tester mancini."], a:1, e:"Significa spostare le attività di testing all'inizio (a sinistra) del ciclo di vita per prevenire difetti prematuramente.", c:"2.1 Modelli di ciclo di vita"},
{q:"Chi è il principale responsabile per l'esecuzione del Component Testing?", o:["A. Il Tester Indipendente.","B. L'Utente Finale.","C. Lo Sviluppatore.","D. Il Project Manager."], a:2, e:"Il test di componente (o unitario) è tipicamente scritto ed eseguito dallo sviluppatore del codice.", c:"2.2.1 Test di componente"},
{q:"Quale tipo di Integration Testing si concentra sulle interazioni tra sistemi diversi?", o:["A. Component Integration Testing.","B. System Integration Testing.","C. User Integration Testing.","D. Operational Integration Testing."], a:1, e:"Il System Integration Testing verifica le interfacce e le interazioni tra sistemi interi o microservizi separati.", c:"2.2.2 Test di integrazione"},
{q:"Qual è l'obiettivo principale del System Testing?", o:["A. Verificare singole righe di codice.","B. Valutare il comportamento dell'intero sistema rispetto alle specifiche di sistema/requisiti.","C. Verificare che l'utente sappia usare il manuale.","D. Gestire i rilasci del codice sorgente."], a:1, e:"Il system testing verifica il sistema nel suo complesso, solitamente eseguito da tester indipendenti.", c:"2.2.3 Test di sistema"},
{q:"Qual è l'obiettivo principale dell'User Acceptance Testing (UAT)?", o:["A. Trovare il maggior numero di bug possibile.","B. Costruire fiducia che il sistema soddisfi le esigenze del business e degli utenti.","C. Verificare la copertura del codice.","D. Testare la velocità del database."], a:1, e:"L'UAT non è focalizzato sul trovare difetti tecnici, ma sul confermare (costruire fiducia) che il sistema sia pronto per l'uso operativo.", c:"2.2.4 Test di accettazione"},
{q:"Che cos'è un test 'Funzionale'?", o:["A. Un test che verifica 'come' il sistema lavora (es. performance).","B. Un test che verifica 'cosa' fa il sistema (es. calcoli, regole di business).","C. Un test eseguito solo dagli utenti.","D. Un test della struttura del codice."], a:1, e:"Il testing funzionale verifica 'cosa' fa il sistema basandosi sui requisiti funzionali (le funzionalità).", c:"2.3.1 Tipi di test"},
{q:"Quale dei seguenti è un test 'Non Funzionale'?", o:["A. Testare il login con password errata.","B. Testare che il carrello sommi i prezzi.","C. Testare il tempo di caricamento della pagina (Performance).","D. Testare l'invio di un'email."], a:2, e:"I test non funzionali misurano caratteristiche di qualità (come performance, usabilità, sicurezza), ovvero 'come' funziona il sistema.", c:"2.3.1 Tipi di test"},
{q:"Perché si esegue il Test di Regressione?", o:["A. Per confermare che un bug è stato fixato.","B. Per verificare che una modifica non abbia causato malfunzionamenti in aree non modificate.","C. Per testare una nuova feature appena sviluppata.","D. Per testare l'hardware."], a:1, e:"La regressione verifica gli effetti collaterali indesiderati delle modifiche su parti di software che prima funzionavano.", c:"2.3.2 Test correlati alle modifiche"},
{q:"Quale evento innesca tipicamente il Test di Manutenzione?", o:["A. L'inizio di un nuovo progetto da zero.","B. Il rilascio di una patch (fix), l'aggiornamento di un sistema o la sua migrazione.","C. La scrittura dei requisiti.","D. L'assunzione di un nuovo tester."], a:1, e:"La manutenzione si esegue su software già in produzione per modifiche, migrazioni o pensionamento.", c:"2.4 Test di Manutenzione"},
{q:"Cos'è l'Analisi d'Impatto (Impact Analysis)?", o:["A. Misurare l'impatto del software sulle vendite.","B. Valutare quali parti del sistema potrebbero essere colpite da una modifica per definire il perimetro di test.","C. Contare i click degli utenti.","D. Calcolare il ROI del test."], a:1, e:"L'analisi d'impatto valuta le conseguenze di una modifica per identificare le aree a rischio e decidere i test di regressione necessari.", c:"2.4.2 Analisi d'impatto"},

// --- CAP 3: TEST STATICO ---
{q:"Qual è una caratteristica distintiva del Test Statico?", o:["A. Richiede l'esecuzione del codice.","B. Viene eseguito solo alla fine del progetto.","C. Valuta i prodotti di lavoro senza eseguire il software.","D. È costoso e trova pochi difetti."], a:2, e:"Il test statico comprende le revisioni (reviews) e l'analisi statica (tools) e si fa senza eseguire il codice.", c:"3.1 Fondamenti"},
{q:"Quale dei seguenti NON è un prodotto di lavoro tipicamente sottoposto a revisione?", o:["A. Specifiche dei requisiti.","B. Storie utente (User Stories).","C. Server di produzione.","D. Codice sorgente."], a:2, e:"I server non sono documenti o codice. Il test statico si applica a prodotti di lavoro testuali o modelli.", c:"3.1 Fondamenti"},
{q:"Quale tipo di difetto è molto più facile da trovare con il test statico che con il test dinamico?", o:["A. Un memory leak a runtime.","B. Ambiguità e omissioni nei requisiti.","C. Un problema di rete.","D. Un collo di bottiglia di memoria."], a:1, e:"Le ambiguità nei requisiti si scovano leggendo il documento. Se arrivano al test dinamico, spesso il software è stato costruito male.", c:"3.1.2 Vantaggi"},
{q:"In una Revisione Formale, qual è la responsabilità principale dell''Autore'?", o:["A. Guidare il meeting.","B. Scrivere i difetti e le metriche.","C. Rispondere alle domande sul prodotto di lavoro e correggere i difetti trovati.","D. Approvare il documento."], a:2, e:"L'autore ha creato il documento, lo spiega, riceve il feedback e applica le correzioni dopo la riunione.", c:"3.2.2 Ruoli"},
{q:"Chi ha il compito di gestire il tempo e mediare i conflitti in un'ispezione?", o:["A. Il Manager.","B. Il Moderatore.","C. Il Scribe (verbalizzante).","D. Il Tester."], a:1, e:"Il moderatore (o facilitatore) garantisce il corretto svolgimento del meeting e la gestione del team.", c:"3.2.2 Ruoli"},
{q:"Quale tipo di revisione è solitamente la PIÙ formale?", o:["A. Revisione Informale.","B. Walkthrough.","C. Revisione Tecnica.","D. Ispezione (Inspection)."], a:3, e:"L'Ispezione è rigidamente formale, basata su metriche, liste di controllo (checklist) e ruoli definiti.", c:"3.2.3 Tipi di revisioni"},
{q:"Quale tipo di revisione è guidato dall'Autore del documento?", o:["A. Ispezione.","B. Walkthrough.","C. Audit.","D. Peer review informale."], a:1, e:"Nel Walkthrough, l'autore guida il team attraverso il documento passo passo per raccogliere feedback.", c:"3.2.3 Tipi di revisioni"},
{q:"Quale delle seguenti è una tecnica di revisione basata sui ruoli (Role-based review)?", o:["A. I revisori leggono il documento cercando solo errori grammaticali.","B. I revisori assumono prospettive diverse (es. utente finale, amministratore di sistema, tester di performance).","C. L'autore fa tutto da solo.","D. Si usa un tool automatico."], a:1, e:"La revisione basata sui ruoli assegna ai revisori punti di vista specifici per coprire vari aspetti (sicurezza, usabilità, manutenzione).", c:"3.2.4 Tecniche di revisione"},

// --- CAP 4: TECNICHE DI TEST (Molte K3) ---
{q:"A cosa serve una tecnica di test?", o:["A. A scrivere codice più velocemente.","B. A definire il budget del progetto.","C. Ad aiutare a identificare le condizioni di test, i casi di test e i dati di test.","D. A compilare il codice."], a:2, e:"Le tecniche di test (es. BVA, EP) sono metodi sistematici per derivare i casi di test e i dati in modo efficace.", c:"4.1 Tecniche di test"},
{q:"Quale tecnica Black-Box divide gli input in gruppi che dovrebbero essere elaborati nello stesso modo?", o:["A. State Transition.","B. Boundary Value Analysis (BVA).","C. Equivalence Partitioning (EP).","D. Use Case Testing."], a:2, e:"Il partizionamento di equivalenza raggruppa i dati in classi (valide e non valide) presumendo che il sistema li tratti allo stesso modo.", c:"4.2.1 EP"},
{q:"Un campo accetta password lunghe da 6 a 12 caratteri. Quali sono le partizioni di equivalenza (EP) per la lunghezza?", o:["A. < 6, tra 6 e 12.","B. = 6, = 12.","C. < 6 (non valida), da 6 a 12 (valida), > 12 (non valida).","D. Solo da 6 a 12."], a:2, e:"Esistono 3 partizioni: una valida (6-12) e due non valide (minore di 6, maggiore di 12).", c:"4.2.1 EP"},
{q:"Applicando l'Analisi dei Valori Limite (BVA) a 2 punti al campo password da 6 a 12 caratteri, quali lunghezze testi?", o:["A. 5, 6, 12, 13","B. 6, 12","C. 5, 6, 7, 11, 12, 13","D. 0, 6, 12, 100"], a:0, e:"La BVA a due punti testa il confine e l'adiacente. Limiti: 6 e 12. Valori: 5 (fuori), 6 (dentro), 12 (dentro), 13 (fuori).", c:"4.2.2 BVA"},
{q:"Un e-commerce offre spedizione gratuita se il totale è MAGGIORE O UGUALE a 50€. Quali valori testi con BVA a 2 punti?", o:["A. 49, 50","B. 50, 51","C. 49, 50, 51","D. 0, 50, 100"], a:0, e:"Il confine è 50. Il limite inferiore valido è 50. Il valore adiacente non valido è 49 (assumendo numeri interi).", c:"4.2.2 BVA"},
{q:"Quale tecnica Black-Box è ideale per testare regole di business complesse con condizioni logiche multiple (AND/OR)?", o:["A. Tabella delle Decisioni (Decision Table).","B. State Transition.","C. BVA.","D. Statement Testing."], a:0, e:"Le Decision Tables catturano combinazioni logiche di condizioni (es. se A=vero e B=falso) e le azioni risultanti.", c:"4.2.3 Decision Table"},
{q:"In una Tabella delle Decisioni con 3 condizioni booleane (Vero/Falso), quanti casi (colonne/regole) ci sono al massimo?", o:["A. 3","B. 6","C. 8","D. 9"], a:2, e:"Il numero di combinazioni è 2^N. Con 3 condizioni booleane, le combinazioni (regole) possibili sono 2^3 = 8.", c:"4.2.3 Decision Table"},
{q:"Stai testando un carrello online. Gli stati sono: Vuoto, In compilazione, Pagato, Spedito. Quale tecnica usi?", o:["A. Use Case Testing.","B. State Transition Testing.","C. EP.","D. Decision Coverage."], a:1, e:"State Transition Testing modella le entità che passano attraverso stati diversi in risposta a eventi (es. click su 'Paga').", c:"4.2.4 State Transition"},
{q:"Quale tecnica si basa sui casi d'uso (Use Case) che rappresentano l'interazione tra attori (es. utenti) e il sistema?", o:["A. Use Case Testing.","B. BVA.","C. Statement Coverage.","D. Error Guessing."], a:0, e:"L'Use Case Testing è una tecnica black-box che deriva test dai flussi principali e alternativi descritti nei casi d'uso.", c:"4.2.5 Use Case Testing"},
{q:"Quale tra le seguenti è una tecnica WHITE-BOX?", o:["A. Partizionamento di equivalenza.","B. Analisi dei valori limite.","C. Statement Testing (Copertura delle istruzioni).","D. Test Esplorativo."], a:2, e:"Le tecniche White-Box si basano sulla struttura interna del codice (es. istruzioni, percorsi, decisioni).", c:"4.3 White-Box"},
{q:"Cos'è la 'Statement Coverage' (Copertura delle istruzioni)?", o:["A. La percentuale di requisiti testati.","B. La percentuale di istruzioni eseguibili nel codice attivate dai test.","C. La percentuale di bug trovati.","D. La percentuale di percorsi decisionali."], a:1, e:"Misura quante righe di codice eseguibile (statements) sono state attraversate durante l'esecuzione della test suite.", c:"4.3.1 Statement Coverage"},
{q:"Se un frammento di codice ha un'istruzione IF (senza ELSE), quanti casi di test servono per raggiungere il 100% di Statement Coverage e quanti per il 100% Decision Coverage?", o:["A. 1 per Statement, 1 per Decision","B. 2 per Statement, 1 per Decision","C. 1 per Statement (che entra nell'IF), 2 per Decision (Vero e Falso)","D. 2 per entrambi"], a:2, e:"Per lo statement basta eseguire l'IF come Vero per passare dentro al blocco. Per decision, devi testare l'IF come Vero e l'IF come Falso (2 casi).", c:"4.3 Coverage"},
{q:"Un codice ha la struttura: IF (X > 0) { print('Positivo'); }. Se uso X=5, che coperture ho raggiunto?", o:["A. 100% Statement, 50% Decision","B. 100% Statement, 100% Decision","C. 50% Statement, 50% Decision","D. 0% Statement, 100% Decision"], a:0, e:"Con X=5, entro nell'IF. Tutte le istruzioni sono eseguite (100% statement). Ma non ho testato il caso Falso dell'IF (50% decision).", c:"4.3 Coverage"},
{q:"Quale tecnica si basa sull'esperienza del tester per 'indovinare' dove si nascondono i difetti, senza una struttura formale?", o:["A. Error Guessing.","B. Decision Table.","C. State Transition.","D. EP."], a:0, e:"Error guessing si affida all'intuizione e all'esperienza passata per anticipare i difetti classici (es. date bisestili, zero, null).", c:"4.4.1 Error Guessing"},
{q:"Quale tecnica prevede che progettazione dei test, esecuzione e apprendimento avvengano simultaneamente?", o:["A. Test Scriptato formale.","B. Test Esplorativo (Exploratory Testing).","C. Analisi statica.","D. Decision Coverage."], a:1, e:"Nel test esplorativo il tester esplora l'app dinamicamente, guidato da un charter, progettando test ed eseguendoli al volo.", c:"4.4.2 Test Esplorativo"},
{q:"Che cos'è il test basato su Checklist?", o:["A. Un'esecuzione automatizzata in Python.","B. Una tecnica basata sull'esperienza in cui i tester usano un elenco di condizioni o controlli da verificare.","C. Una tecnica white-box.","D. Il test dei valori limite."], a:1, e:"Le checklist forniscono una guida ad alto livello (es. 'Controlla tutti i campi obbligatori') lasciando al tester libertà su come farlo.", c:"4.4.3 Checklist-based testing"},

// --- CAP 5: GESTIONE ---
{q:"Chi beneficia maggiormente dell'indipendenza nel testing?", o:["A. Il tester, perché viene pagato di più.","B. L'organizzazione, perché i tester indipendenti sono più oggettivi e trovano difetti diversi dagli autori.","C. Gli sviluppatori, perché non devono più testare.","D. Nessuno."], a:1, e:"L'indipendenza riduce il bias di conferma: chi non ha scritto il codice lo osserva con occhi critici e aspettative diverse.", c:"5.1 Organizzazione"},
{q:"Qual è un compito tipico di un Test Manager?", o:["A. Scrivere il codice per fixare i bug.","B. Configurare la pipeline CI/CD.","C. Pianificare le attività, monitorare i progressi, gestire i rischi e scrivere i report di test.","D. Compilare il database."], a:2, e:"Il Test Manager si occupa della gestione (pianificazione, controllo, reportistica, risorse) mentre i Tester si occupano dell'esecuzione pratica.", c:"5.1.2 Ruoli"},
{q:"Cos'è un Test Plan (Piano di Test)?", o:["A. L'elenco passo-passo dei click da fare sull'app.","B. Un documento che descrive obiettivi, approccio, risorse e schedulazione delle attività di test previste.","C. Il codice sorgente del test automatico.","D. Un report dei bug a fine progetto."], a:1, e:"Il Test Plan è il documento manageriale fondamentale che definisce COME e QUANDO verranno fatti i test.", c:"5.2 Test Planning"},
{q:"Quali dei seguenti sono tipici 'Criteri di Ingresso' (Entry Criteria) per iniziare l'esecuzione del test?", o:["A. Zero difetti critici aperti.","B. L'ambiente di test è configurato, i dati sono pronti e il codice è stato rilasciato.","C. Il budget è esaurito.","D. Il test di accettazione utente è completato."], a:1, e:"I criteri di ingresso definiscono le precondizioni affinché un'attività di test possa iniziare in modo utile e senza blocchi.", c:"5.2.3 Entry/Exit criteria"},
{q:"Come viene stimato lo sforzo di test tramite la tecnica basata sulle metriche?", o:["A. Chiedendo agli esperti.","B. Facendo una partita a Planning Poker.","C. Basandosi sui dati storici di progetti passati simili (es. tempo medio per eseguire un test case).","D. Indovinando."], a:2, e:"L'approccio basato sulle metriche usa dati e formule misurabili dal passato. L'approccio basato sull'esperienza usa esperti (es. Planning Poker).", c:"5.2.6 Tecniche di stima"},
{q:"Cosa fa il Configuration Management in ambito testing?", o:["A. Gestisce i turni dei dipendenti.","B. Gestisce il server di rete.","C. Traccia le versioni dei requisiti, del codice, dei tool e dei casi di test per garantire la coerenza.","D. Calcola i costi."], a:2, e:"Garantisce che tu sappia sempre ESATTAMENTE quale versione del software stai testando con quale versione dei test.", c:"5.4 Configuration Management"},
{q:"Qual è la definizione di Rischio?", o:["A. La certezza che il software fallirà.","B. La probabilità che si verifichi un evento negativo moltiplicata per il suo impatto.","C. Un difetto trovato in produzione.","D. Un errore di sintassi."], a:1, e:"Il rischio si valuta in base a due fattori: Probabilità (likelihood) x Impatto (impact).", c:"5.5 Rischio"},
{q:"Quale dei seguenti è un Rischio di Prodotto (Product Risk)?", o:["A. Il lead tester si dimette.","B. L'ambiente di test non è disponibile.","C. Il software calcola in modo errato gli interessi di un mutuo, violando la legge.","D. Il budget per il testing viene tagliato."], a:2, e:"I rischi di prodotto riguardano malfunzionamenti o difetti del software. Gli altri sono rischi di PROGETTO (risorse, tempo, ambiente).", c:"5.5 Rischio"},
{q:"A cosa serve l'Analisi dei Rischi nel testing (Risk-based testing)?", o:["A. A testare prima e con maggiore profondità le aree a rischio più alto.","B. Ad annullare il progetto se ci sono rischi.","C. A licenziare chi commette errori.","D. A testare tutto il software nello stesso identico modo."], a:0, e:"Nel risk-based testing, lo sforzo viene allocato proporzionalmente al livello di rischio per massimizzare l'efficacia.", c:"5.5 Rischio"},
{q:"In un Defect Report (Rapporto Anomalie), perché si usano gli 'Steps to reproduce' (Passaggi per riprodurre)?", o:["A. Per annoiare lo sviluppatore.","B. Per dimostrare che il tester ha lavorato.","C. Per permettere allo sviluppatore di ricreare il difetto sul suo PC, analizzarlo e correggerlo.","D. Per calcolare la severità."], a:2, e:"Se un difetto non è riproducibile, è quasi impossibile da correggere. I passaggi sono l'elemento più vitale del report.", c:"5.6 Gestione difetti"},
{q:"Qual è la differenza tra Priorità e Severità in un bug?", o:["A. Sono identiche.","B. La Priorità indica l'urgenza di risoluzione per il business; la Severità indica l'impatto tecnico sul sistema.","C. La Severità la decide il CEO, la Priorità il tester.","D. La Priorità riguarda il codice, la Severità la UI."], a:1, e:"Esempio: un refuso nel logo ha bassa severità (tutto funziona) ma alta priorità (danno d'immagine enorme, fix immediato).", c:"5.6 Gestione difetti"},

// --- CAP 6: STRUMENTI ---
{q:"Quale strumento è progettato per supportare la creazione, esecuzione e monitoraggio di test automatici sulla GUI o API?", o:["A. Strumento per l'analisi statica.","B. Strumento di Test Execution (Esecuzione del test).","C. Strumento di Test Management.","D. Modellatore UML."], a:1, e:"I Test Execution Tools (come Selenium, Appium, Cypress) automatizzano i click e l'interazione con l'app.", c:"6.1.1 Strumenti"},
{q:"Cos'è uno strumento di Test Management (Gestione del test)?", o:["A. Un tool per testare le performance di rete.","B. Un tool (es. Jira, TestRail, ALM) per gestire test cases, tracciabilità, requisiti ed execution status.","C. Un tool che analizza il codice.","D. Un framework per Java."], a:1, e:"Gli strumenti di Test Management coordinano l'intero processo di test e offrono cruscotti (dashboard) e metriche.", c:"6.1.1 Strumenti"},
{q:"Quale tipo di strumento serve per scoprire colli di bottiglia o verificare se il sistema regge 10.000 utenti concorrenti?", o:["A. Strumento per l'analisi del codice.","B. Strumento di Performance / Load Testing.","C. Strumento di Configuration Management.","D. Strumento di Incident Management."], a:1, e:"Strumenti come JMeter o LoadRunner simulano carichi massicci per testare le performance.", c:"6.1.1 Strumenti"},
{q:"Qual è il rischio principale dell'introduzione dell'Automazione dei test in un'azienda?", o:["A. Che il software non abbia più difetti.","B. Sottostimare il costo iniziale, il tempo per costruire il framework e lo sforzo di manutenzione.","C. Che i tester manuali vengano tutti licenziati il giorno dopo.","D. Che i test girino troppo velocemente."], a:1, e:"L'automazione richiede un forte investimento iniziale e manutenzione continua. Non è 'magia' a costo zero.", c:"6.2 Rischi e Benefici"},
{q:"Perché si dovrebbe avviare un 'Progetto Pilota' (Proof of Concept) prima di comprare un nuovo tool costoso?", o:["A. Per usarlo gratis e poi restituirlo.","B. Per valutarne l'adattabilità ai processi aziendali, valutarne il ROI e stabilire best practice prima di estenderlo a tutti.","C. Per nasconderlo ai manager.","D. Per testarlo sui clienti."], a:1, e:"Il progetto pilota serve ad abbattere i rischi di adozione, imparare i limiti del tool e capire come integrarlo nel workflow.", c:"6.3 Introduzione di uno strumento"},
{q:"A cosa serve uno strumento di Data Preparation (Preparazione dei dati)?", o:["A. A fare backup dei server.","B. A generare, manipolare o anonimizzare grandi quantità di dati (es. finte carte di credito) da usare nei test.","C. A formattare i dischi.","D. A calcolare le metriche."], a:1, e:"Soprattutto per privacy (GDPR) e volume, questi strumenti preparano dati validi e sintetici per i database di test.", c:"6.1.1 Strumenti"},
{q:"Quale vantaggio si ottiene usando un tool per l'Analisi Statica del codice?", o:["A. Trova i difetti a runtime, quando il software è in uso.","B. Permette l'individuazione di violazioni di standard, vulnerabilità e codice morto PRIMA dell'esecuzione.","C. Genera test automatici.","D. Compila il codice in automatico."], a:1, e:"L'analisi statica agisce in anticipo (Shift-Left) senza eseguire il software, risparmiando molto tempo e denaro.", c:"6.1.2 Vantaggi"},

// --- DOMANDE AGGIUNTIVE MISTE PER VOLUME E RIPASSO (Tecniche e Fondamenti) ---
{q:"Se hai un requisito che dice: 'Valori accettati da 1 a 10'. Quale tecnica di test sceglieresti per massimizzare la copertura con il minor numero di test?", o:["A. Statement Coverage.","B. BVA (Analisi dei valori limite).","C. Use Case.","D. Error Guessing."], a:1, e:"La BVA è progettata specificamente per testare i bordi dei range continui o discreti, dove si verificano più bug.", c:"4.2 BVA"},
{q:"In un test basato sulle transizioni di stato (State Transition), cosa rappresenta un 'Evento'?", o:["A. Lo stato finale.","B. L'azione che causa il passaggio (transizione) del sistema da uno stato all'altro (es. 'Inserimento PIN corretto').","C. Un errore a schermo.","D. Un tester."], a:1, e:"Il sistema cambia stato a causa di un evento. Es: Stato 'Schermo spento', Evento 'Premi tasto', Transizione a Stato 'Schermo acceso'.", c:"4.2.4 State Transition"},
{q:"Quanti principi del testing ISTQB esistono?", o:["A. 5","B. 7","C. 10","D. 12"], a:1, e:"I principi sono 7: 1. Mostra difetti 2. Esaustivo impossibile 3. Precoce 4. Raggruppamento 5. Pesticida 6. Contesto 7. Fallacia assenza.", c:"1.3 Sette principi"},
{q:"Cosa afferma il Principio 7 'Fallacia dell'assenza di difetti'?", o:["A. Nessun software ha bug.","B. Anche se risolvi tutti i bug trovati e raggiungi zero difetti noti, il software potrebbe essere inutile se non soddisfa i bisogni dell'utente.","C. L'assenza di difetti è garantita dall'automazione.","D. Gli utenti non trovano mai difetti."], a:1, e:"Un sistema perfetto tecnicamente ma inutile o non usabile è comunque un fallimento del progetto.", c:"1.3 Sette principi"},
{q:"Come viene definito un difetto (defect/bug) nell'ISTQB?", o:["A. Un'azione umana che produce un risultato errato.","B. Un'imperfezione nel codice o nel documento che può causare un guasto.","C. Il fallimento del sistema visibile all'utente.","D. Un problema hardware."], a:1, e:"Azione umana -> Errore (Error). Imperfezione -> Difetto (Defect/Bug). Quando il difetto viene eseguito -> Guasto/Malfunzionamento (Failure).", c:"1.2 Errori, difetti, guasti"},
{q:"Un utente digita male una data. Questo è un:", o:["A. Errore (Error/Mistake)","B. Difetto (Defect)","C. Guasto (Failure)","D. Anomalia"], a:0, e:"L'azione umana scorretta è l'Errore. Se questo introduce codice sbagliato, crea un Difetto. Se il difetto blocca l'app, è un Guasto.", c:"1.2 Errori, difetti, guasti"},
{q:"Nel testing Agile, chi è responsabile della qualità?", o:["A. Solo il Product Owner.","B. Solo il Tester Indipendente.","C. L'intero Team (Sviluppatori, Tester, Business).","D. Lo Scrum Master."], a:2, e:"L'approccio Agile (Whole Team Approach) promuove la responsabilità condivisa della qualità tra tutti i membri del team.", c:"2.1.1 Sviluppo Agile"},
{q:"Cos'è un Test Oracle (Oracolo di test)?", o:["A. Una persona molto esperta.","B. La fonte per determinare il risultato atteso di un test (es. le specifiche, uno standard, o un software precedente).","C. Un database SQL.","D. Un tool di generazione dati."], a:1, e:"L'oracolo è la fonte di verità con cui il tester confronta l'output del sistema per capire se il test è Pass o Fail.", c:"1.4.2 Progettazione test"},
{q:"Nella tracciabilità (Traceability), collegare un Test Case al Requisito di Business originario serve a:", o:["A. Valutare l'impatto di un cambiamento al requisito e misurare la copertura dei requisiti.","B. Sapere quale sviluppatore punire.","C. Calcolare le righe di codice.","D. Automatizzare il test."], a:0, e:"La tracciabilità bi-direzionale garantisce di sapere quali test coprono quali requisiti e aiuta l'analisi d'impatto.", c:"1.4.4 Tracciabilità"},
{q:"Quale approccio si focalizza su un alto livello di automazione fin dall'inizio, con i test scritti prima del codice?", o:["A. TDD (Test-Driven Development).","B. Waterfall.","C. V-Model manuale.","D. Exploratory Testing."], a:0, e:"Nel TDD si scrivono prima i test unitari che falliscono, poi si scrive il codice per farli passare (Red-Green-Refactor).", c:"2.1.1 Modelli iterativi e incrementali"},
{q:"L'Integration Testing può essere diviso in due macro-categorie. Quali?", o:["A. Component Integration e System Integration.","B. Unit Integration e User Integration.","C. Alpha Integration e Beta Integration.","D. Black-box Integration e White-box Integration."], a:0, e:"Component Integration (tra moduli/classi interne) e System Integration (tra l'intero sistema e sistemi esterni/API).", c:"2.2.2 Test di integrazione"},
{q:"Quale dei seguenti NON è un fattore che innesca (trigger) il Maintenance Testing?", o:["A. L'applicazione di una patch di sicurezza (Modifica).","B. Lo spostamento dell'app dal Cloud AWS al Cloud Azure (Migrazione).","C. L'inizio della raccolta dei requisiti per un'app completamente nuova.","D. Lo spegnimento definitivo di un vecchio server (Ritiro)."], a:2, e:"Il maintenance testing si applica a sistemi esistenti, non a nuovi progetti che partono da zero.", c:"2.4 Test di Manutenzione"},
{q:"Durante quale fase di un'Ispezione (Inspection) formale si trovano la maggior parte dei difetti?", o:["A. Pianificazione.","B. Preparazione individuale (Individual preparation).","C. Durante il kickoff.","D. Durante il Rework (correzione)."], a:1, e:"Nell'ispezione, i revisori leggono da soli il documento prima del meeting. È in questa fase che scovano la maggior parte dei bug.", c:"3.2.2 Processo di revisione"},
{q:"Se hai l'istruzione: IF (età >= 18 AND patente == true). Per avere il 100% di copertura delle DECISIONI, quanti casi di test servono?", o:["A. 1","B. 2","C. 3","D. 4"], a:1, e:"Decision coverage guarda il risultato finale dell'IF (Vero o Falso). Bastano 2 casi: uno che renda l'IF globale Vero, e uno Falso.", c:"4.3.2 Copertura delle decisioni"},
{q:"Il Test di Accettazione è spesso suddiviso in vari tipi. Quale NON è un tipo di test di accettazione?", o:["A. User Acceptance Testing (UAT).","B. Operational Acceptance Testing (OAT).","C. Component Acceptance Testing (CAT).","D. Contractual & Regulatory Acceptance Testing."], a:2, e:"Il CAT non esiste. Esistono l'UAT (Utenti), OAT (Amministratori di sistema), Alpha/Beta e di conformità contrattuale.", c:"2.2.4 Test di accettazione"},
{q:"Come si calcola la Statement Coverage (copertura delle istruzioni)?", o:["A. (Numero di istruzioni testate / Numero totale di istruzioni testabili) x 100","B. (Bug trovati / Istruzioni totali) x 100","C. (Test falliti / Test totali) x 100","D. Righe di commento testate."], a:0, e:"La formula è semplice: quante linee eseguibili ho attraversato diviso quante linee eseguibili esistono in totale (in percentuale).", c:"4.3.1 Statement Coverage"},
{q:"Un team stima l'effort di test basandosi su quanto tempo hanno impiegato l'anno scorso per un progetto identico. Che tipo di stima stanno usando?", o:["A. Basata sull'esperienza (Expert-based).","B. Basata sulle metriche (Metrics-based).","C. Planning Poker.","D. WBS (Work Breakdown Structure)."], a:1, e:"L'uso di dati storici precisi o formule (es. '1 test case = 30 minuti') è un approccio basato sulle metriche.", c:"5.2.6 Stima"},
{q:"Qual è l'obiettivo principale del monitoraggio (Test Monitoring)?", o:["A. Controllare i log del server di produzione.","B. Raccogliere dati continui sulle metriche di test per confrontare il progresso reale con quello pianificato nel Test Plan.","C. Punire i tester in ritardo.","D. Scrivere codice di automazione."], a:1, e:"Il monitoraggio fornisce visibilità sullo stato di avanzamento. Se si è in ritardo, interviene il Controllo (Test Control).", c:"5.3 Monitoraggio e controllo"},

// ===== NUOVE DOMANDE — ESPANSIONE v2 =====

// --- CAP 1: FONDAMENTI (15 nuove) ---
{q:"Cos'è la Root Cause Analysis (RCA) nel contesto del testing?", o:["A. Un'analisi economica per calcolare il ROI del testing.","B. Un processo per identificare la causa principale di un difetto o problema, al fine di prevenirne il ripresentarsi.","C. Un report di fine progetto inviato al cliente.","D. Un tipo di test di regressione."], a:1, e:"La RCA va oltre la correzione del sintomo: cerca la causa profonda che ha generato il problema (es. processo di revisione mancante, formazione inadeguata) per eliminarlo alla radice.", c:"1.1 Obiettivi"},
{q:"Quale delle seguenti sequenze descrive correttamente la catena 'Error → Defect → Failure'?", o:["A. Un tester sbaglia un test, creando un difetto nel report, causando un guasto nel sistema.","B. Uno sviluppatore commette un errore umano (Error) che introduce un'imperfezione nel codice (Defect); quando quel codice viene eseguito, si produce un comportamento inatteso (Failure).","C. Un requisito errato causa un guasto diretto nel sistema senza passare per il difetto.","D. Un guasto viene rilevato, diventa un difetto e poi viene classificato come errore."], a:1, e:"La catena ISTQB è: Error (azione umana) → Defect/Bug (imperfezione artefatta) → Failure (deviazione dal comportamento atteso durante l'esecuzione). Un difetto nel codice non sempre porta a un failure; dipende dall'esecuzione del percorso difettoso.", c:"1.2 Errori, difetti, guasti"},
{q:"Un difetto latente nel codice di gestione degli errori non si manifesta mai durante i test normali. Come viene chiamato questo scenario?", o:["A. Un Failure nascosto.","B. Un difetto dormiente (Latent Defect) che diventa un Failure solo in specifiche condizioni di esecuzione.","C. Un Error del tester.","D. Un rischio di progetto."], a:1, e:"I difetti dormenti esistono nel codice ma non producono un Failure finché non viene eseguito il percorso che li contiene (es. solo con determinati dati di input o condizioni di sistema).", c:"1.2 Errori, difetti, guasti"},
{q:"Quale standard ISO/IEC definisce le caratteristiche di qualità del software (es. Funzionalità, Affidabilità, Usabilità)?", o:["A. ISO 9001","B. ISO/IEC 25010","C. IEEE 829","D. ISO/IEC 12207"], a:1, e:"ISO/IEC 25010 (SQuaRE) è lo standard di riferimento ISTQB per la qualità del prodotto software. Definisce 8 caratteristiche principali tra cui Functional Suitability, Performance Efficiency, Usability, Reliability, Security, Maintainability, Compatibility e Portability.", c:"1.1 Obiettivi"},
{q:"Nel contesto del testing, cosa si intende per 'Qualità del processo' contrapposta alla 'Qualità del prodotto'?", o:["A. La qualità del processo riguarda il software finale; la qualità del prodotto riguarda i test.","B. La qualità del processo misura l'efficienza e l'efficacia del processo di sviluppo/test; la qualità del prodotto misura le caratteristiche del software consegnato (conformità ai requisiti, affidabilità, ecc.).","C. Sono sinonimi e non c'è differenza.","D. La qualità del prodotto è solo estetica (UI)."], a:1, e:"Migliorare la qualità del processo (es. migliori revisioni, CI/CD) porta indirettamente a un prodotto di qualità superiore. Il testing mira a entrambe: valuta il prodotto e contribuisce a migliorare il processo.", c:"1.1 Obiettivi"},
{q:"Quale tipo di Acceptance Testing verifica che il sistema sia pronto per le operazioni in produzione, inclusi backup, gestione degli utenti e procedure di disaster recovery?", o:["A. User Acceptance Testing (UAT)","B. Operational Acceptance Testing (OAT)","C. Contractual Acceptance Testing","D. Alpha Testing"], a:1, e:"L'OAT (Operational Acceptance Testing) è eseguito tipicamente da amministratori di sistema e verifica gli aspetti operativi: backup/restore, gestione utenti, installazione, monitoraggio. Si concentra su 'come gira in produzione', non sulle funzionalità di business.", c:"2.2.4 Test di accettazione"},
{q:"Cosa si intende per 'Validation' (Validazione) nel testing, in contrasto con 'Verification' (Verifica)?", o:["A. Verification = stiamo costruendo il prodotto giusto? Validation = stiamo costruendo il prodotto nel modo giusto?","B. Verification = stiamo costruendo il prodotto nel modo giusto (rispettando le specifiche)? Validation = stiamo costruendo il prodotto giusto (soddisfa i bisogni reali dell'utente)?","C. Sono sinonimi.","D. Validation riguarda solo il testing automatico."], a:1, e:"Celebre distinzione di Boehm: Verification ('Are we building the product right?') controlla la conformità alle specifiche; Validation ('Are we building the right product?') controlla che il prodotto soddisfi i bisogni e le aspettative reali dell'utente.", c:"1.1 Obiettivi"},
{q:"Cosa misura la caratteristica di qualità 'Reliability' (Affidabilità) secondo ISO/IEC 25010?", o:["A. La velocità di risposta del sistema.","B. La capacità del sistema di svolgere le funzioni specificate in condizioni normali per un periodo di tempo, incluse le capacità di maturità, disponibilità, tolleranza ai guasti e recuperabilità.","C. La facilità con cui il codice può essere modificato.","D. Il numero di funzionalità implementate."], a:1, e:"Reliability comprende: Maturity (frequenza dei guasti), Availability (up-time), Fault Tolerance (comportamento in presenza di guasti) e Recoverability (capacità di ripristino dopo un guasto).", c:"1.1 Obiettivi"},
{q:"Quale dei seguenti è un esempio di testing 'Non Funzionale' che verifica la caratteristica 'Security' di ISO 25010?", o:["A. Testare che la funzione di login accetti le credenziali corrette.","B. Eseguire un penetration test per verificare che le password siano salvate cifrate e che non ci siano SQL injection vulnerability.","C. Testare che il carrello sommi correttamente i prezzi.","D. Verificare che l'interfaccia sia disponibile in italiano."], a:1, e:"Security testing verifica la protezione da accessi non autorizzati, vulnerabilità e attacchi. È una caratteristica non funzionale di ISO 25010 (con sotto-caratteristiche: Confidentiality, Integrity, Non-repudiation, Accountability, Authenticity).", c:"2.3.1 Tipi di test"},
{q:"Il Principio 6 dell'ISTQB afferma 'Il testing dipende dal contesto'. Qual è l'implicazione pratica?", o:["A. Tutti i progetti devono usare le stesse tecniche e lo stesso livello di testing.","B. L'approccio di test varia in base al tipo di software, ai rischi, ai vincoli e agli obiettivi: testare un sistema medicale è diverso dal testare un sito e-commerce.","C. Il contesto non influenza il testing.","D. I principi si applicano solo ai grandi progetti."], a:1, e:"Un software safety-critical (es. controllo di un aereo) richiede rigore molto maggiore di un'app mobile semplice. Le tecniche, la copertura e i criteri di uscita si scelgono in base al contesto specifico.", c:"1.3 Sette principi"},
{q:"Cos'è un 'Test Condition' (Condizione di test)?", o:["A. Una precondizione necessaria affinché l'ambiente di test funzioni.","B. Un aspetto testabile del componente o sistema da esercitare da uno o più casi di test.","C. Un sinonimo di 'Test Case'.","D. La valutazione del test al termine dell'esecuzione."], a:1, e:"Una Test Condition è un elemento (aspetto, caratteristica, combinazione di valori) che può essere verificato da uno o più Test Case. Deriva dall'analisi della Test Basis. Esempio: 'Utente non autenticato che accede a pagina riservata'.", c:"1.4 Processo di test"},
{q:"Perché il test precoce (Early Testing / Shift-Left) riduce i costi?", o:["A. Perché si assume meno personale.","B. Perché trovare e correggere un difetto nei requisiti costa molto di meno che trovarlo in produzione (curva dei costi esponenziale).","C. Perché si saltano alcune fasi di testing.","D. Perché i test precoci sono più veloci da eseguire."], a:1, e:"La 'Rule of Ten' illustra che il costo di correzione di un difetto aumenta di un fattore 10 per ogni fase che attraversa: un difetto nei requisiti costa 1x, in design 10x, in codice 100x, in produzione 1000x.", c:"1.3 Sette principi"},
{q:"Nel contesto ISTQB v4.0, quale delle seguenti è una skill non tecnica (soft skill) fondamentale per un tester?", o:["A. Conoscenza di Selenium WebDriver.","B. Capacità di comunicazione efficace, curiosità, pensiero critico e orientamento alla qualità.","C. Programmazione in Java.","D. Conoscenza del protocollo HTTP."], a:1, e:"Le soft skills del tester includono: curiosità (voglia di esplorare), senso critico (mettere in discussione ciò che vede), attenzione ai dettagli, comunicazione (segnalare problemi diplomaticamente) e pensiero analitico.", c:"1.5 Psicologia del testing"},
{q:"Quale delle seguenti situazioni dimostra il 'Paradosso della Fallacia dell'Assenza di Difetti' (Defect-free Fallacy)?", o:["A. Un software con zero bug che non viene mai usato dagli utenti perché non soddisfa le loro esigenze reali.","B. Un software con molti bug ma usato con successo da milioni di persone.","C. Un tester che trova tutti i difetti nel codice.","D. Un sistema che non ha mai subito un failure."], a:0, e:"Il 7° principio dice: eliminare tutti i difetti noti NON garantisce il successo. Se il software non fa ciò che gli utenti vogliono, è inutile indipendentemente dalla sua correttezza tecnica.", c:"1.3 Sette principi"},
{q:"In quale attività del processo di test si producono i 'Test Summary Report'?", o:["A. Test Analysis","B. Test Design","C. Test Completion","D. Test Execution"], a:2, e:"La Test Completion (chiusura del test) è la fase finale in cui si consolidano i risultati, si producono i Test Summary Report, si archiviano gli artefatti di test e si traggono lezioni apprese.", c:"1.4 Processo di test"},

// --- CAP 2: CICLO DI VITA (15 nuove) ---
{q:"Descrivere il ciclo 'Red-Green-Refactor' del TDD.", o:["A. Rosso = build fallita, Verde = build OK, Refactor = deploy.","B. Rosso = scrivi un test che fallisce (perché il codice non esiste), Verde = scrivi il minimo codice per farlo passare, Refactor = migliora il codice senza far fallire i test.","C. Rosso = codice sbagliato, Verde = codice corretto, Refactor = documentazione.","D. Rosso = test manuali, Verde = test automatici, Refactor = rimozione test."], a:1, e:"TDD (Test-Driven Development) segue il ciclo: 1) Scrivi un test unitario che fallisce (Red) 2) Scrivi il codice minimo per farlo passare (Green) 3) Migliora il codice mantenendo i test verdi (Refactor). Questo garantisce copertura totale e design emergente.", c:"2.1.1 TDD"},
{q:"Qual è la differenza principale tra ATDD (Acceptance Test-Driven Development) e TDD?", o:["A. Non c'è differenza pratica.","B. ATDD è focalizzato sui test di accettazione definiti dal business prima dello sviluppo (collaborazione tra business, dev e tester); TDD è focalizzato sui test unitari scritti dagli sviluppatori.","C. ATDD usa solo test manuali; TDD usa solo test automatici.","D. ATDD è una tecnica white-box; TDD è black-box."], a:1, e:"ATDD eleva il TDD al livello di accettazione: il team definisce insieme i criteri di accettazione (es. con Gherkin) prima di scrivere il codice. TDD opera a livello di unità/componente ed è tipicamente lo sviluppatore che guida.", c:"2.1.1 ATDD"},
{q:"Cosa descrive il formato 'Given/When/Then' usato nel BDD (Behaviour-Driven Development)?", o:["A. Given = il database, When = il codice, Then = il risultato del test.","B. Given = precondizione/contesto, When = azione/evento, Then = risultato atteso. È un linguaggio comune (Gherkin) per descrivere scenari di test comprensibili da tutti.","C. È un formato proprietario di Cucumber e non è standard ISTQB.","D. Given = requisito, When = difetto, Then = correzione."], a:1, e:"Il formato Gherkin (Given/When/Then) del BDD permette di scrivere scenari di test leggibili da business analyst, sviluppatori e tester: es. GIVEN l'utente è sulla pagina login WHEN inserisce credenziali valide THEN viene reindirizzato alla homepage.", c:"2.1.1 BDD"},
{q:"Quale tipo di test è eseguito per verificare le interazioni tra i componenti all'interno dello stesso sistema (es. tra il modulo ordine e il modulo inventario)?", o:["A. System Integration Testing","B. Component Integration Testing","C. User Acceptance Testing","D. Operational Testing"], a:1, e:"Il Component Integration Testing (o Integration Testing di basso livello) verifica le interfacce e le interazioni tra componenti dello stesso sistema. Il System Integration Testing verifica invece le interazioni con sistemi esterni (es. API di pagamento, altri sistemi aziendali).", c:"2.2.2 Test di integrazione"},
{q:"Cos'è il Test di Conferma (Confirmation Test / Re-Test)?", o:["A. Un test che conferma le stime di effort.","B. Un test eseguito dopo la correzione di un difetto per verificare che il difetto sia effettivamente stato risolto.","C. Un test che un utente esegue per confermare i requisiti.","D. Sinonimo di test di regressione."], a:1, e:"Il Confirmation Testing è diverso dal Regression Testing: il confirmation test verifica CHE un difetto specifico sia stato corretto (ri-esegue i test che avevano fallito). Il regression test verifica che la correzione non abbia introdotto nuovi difetti altrove.", c:"2.3.2 Test correlati alle modifiche"},
{q:"In Kanban, come viene gestito il flusso di lavoro nel testing?", o:["A. Con sprint di 2 settimane e cerimonie fisse.","B. Con un flusso continuo (Pull System): le attività di test vengono estratte (pulled) dalla colonna precedente quando c'è capacità disponibile, limitando il WIP (Work In Progress).","C. Con una pianificazione rigida all'inizio del progetto.","D. Kanban non supporta il testing."], a:1, e:"Kanban usa una board visuale con colonne (es. 'Da testare', 'In test', 'Testato'). Il WIP limit per ogni colonna evita il multitasking eccessivo. I tester 'tirano' il lavoro quando hanno capacità, senza sprint fissi.", c:"2.1 Modelli di ciclo di vita"},
{q:"Come il DevOps influenza le pratiche di testing?", o:["A. In DevOps il testing è eliminato perché la continuous delivery garantisce la qualità.","B. DevOps promuove l'integrazione del testing nell'intera pipeline CI/CD: test automatici eseguiti ad ogni commit (continuous testing), feedback rapido agli sviluppatori, e responsabilità condivisa della qualità tra dev e ops.","C. DevOps richiede più tester manuali.","D. DevOps sposta il testing solo in fase di produzione."], a:1, e:"In DevOps, il testing non è una fase separata: è continuo. Ogni commit avvia una pipeline automatica con unit test, integration test, e spesso anche test di sicurezza (SAST/DAST). L'obiettivo è feedback istantaneo ('fail fast').", c:"2.1 DevOps e CI/CD"},
{q:"Qual è l'obiettivo principale della Continuous Integration (CI) in relazione al testing?", o:["A. Deployare automaticamente in produzione ogni feature.","B. Integrare frequentemente il codice di tutti gli sviluppatori in un repository condiviso, eseguendo automaticamente build e test per rilevare conflitti e difetti il prima possibile.","C. Sostituire il testing manuale.","D. Generare automaticamente i requisiti."], a:1, e:"La CI riduce il 'Integration Hell': integrare piccole porzioni di codice frequentemente (anche più volte al giorno) e testarle automaticamente garantisce che i problemi di integrazione vengano scoperti subito, quando sono facili da correggere.", c:"2.1 DevOps e CI/CD"},
{q:"Nel modello a V, a quale livello di test corrisponde il 'System Acceptance Test'?", o:["A. Requisiti di componente","B. Design di sistema","C. Requisiti di business / User Requirements","D. Design architetturale"], a:2, e:"Nel modello a V: Component Test ↔ Component Design, Component Integration Test ↔ High-level Design, System Test ↔ System Requirements, Acceptance Test ↔ Business/User Requirements. Ogni livello di test corrisponde al livello di specifiche corrispondente a sinistra del V.", c:"2.1 Modelli di ciclo di vita"},
{q:"Cosa si intende per 'Whole Team Approach' nel contesto Agile?", o:["A. Tutti i membri del team fanno tutto, incluso sviluppo e amministrazione di sistema.","B. La qualità è responsabilità di tutti i membri del team (sviluppatori, tester, business analyst, PO), che collaborano attivamente anziché lavorare in silos separati.","C. Il team è composto da tester specializzati in ogni area.","D. Solo il team di testing ha visibilità sulla qualità."], a:1, e:"Il Whole Team Approach (approccio dell'intero team) è un principio Agile che abbatte le barriere tra ruoli: sviluppatori scrivono unit test, tester partecipano alla definizione dei requisiti, business analyst contribuiscono ai criteri di accettazione.", c:"2.1.1 Sviluppo Agile"},
{q:"In Scrum, quando si eseguono tipicamente i test di regressione?", o:["A. Solo alla fine dell'ultimo sprint.","B. Una volta alla fine di ogni sprint, come parte della Definition of Done.","C. Continuamente durante lo sprint, spesso automatizzati, e come parte integrante dell'esecuzione dello sprint.","D. Solo quando richiesto dal Product Owner."], a:2, e:"In Scrum ogni sprint deve produrre un incremento 'Done' e potenzialmente rilasciabile. I test di regressione (spesso automatizzati) girano continuamente per garantire che le nuove funzionalità non rompano quelle esistenti. Fanno parte della Definition of Done.", c:"2.1 Modelli di ciclo di vita"},
{q:"Quale tipo di testing verifica che il software funzioni correttamente nell'ambiente reale di esecuzione, incluso il sistema operativo, l'hardware e i servizi di rete?", o:["A. Component Testing","B. System Testing","C. Operational Acceptance Testing (OAT)","D. Alpha Testing"], a:2, e:"L'OAT verifica gli aspetti operativi del sistema nell'ambiente target: gestione utenti, backup/restore, installazione, configurazione, comportamento sotto carico reale. È eseguito prima del go-live per garantire la readiness operativa.", c:"2.2.4 Test di accettazione"},
{q:"Cosa si intende per 'Test di sistema' (System Testing)?", o:["A. Il test di singoli componenti isolati.","B. Il test del comportamento dell'intero sistema integrato rispetto ai requisiti di sistema specificati, solitamente in un ambiente simile a quello di produzione.","C. Il test eseguito dall'utente finale in produzione.","D. Il test dell'hardware."], a:1, e:"Il System Testing considera il sistema come una 'black box' complessiva. Verifica funzionalità end-to-end, caratteristiche non funzionali (performance, sicurezza), e la corretta integrazione di tutti i componenti. È tipicamente eseguito da tester indipendenti.", c:"2.2.3 Test di sistema"},
{q:"Qual è la differenza tra Alpha Testing e Beta Testing?", o:["A. Alpha è fatto dagli utenti in ambiente di produzione; Beta è fatto dagli sviluppatori.","B. Alpha è eseguito presso la sede del fornitore/sviluppatore da un gruppo selezionato di utenti; Beta è eseguito presso i clienti nell'ambiente reale dell'utente finale.","C. Non c'è differenza pratica.","D. Alpha è automatizzato; Beta è manuale."], a:1, e:"Alpha Testing: utenti invitati testano il software in ambiente controllato dello sviluppatore, con supervisione del team. Beta Testing: utenti reali testano in produzione/ambiente proprio, senza supervisione diretta. Entrambi sono forme di acceptance testing.", c:"2.2.4 Test di accettazione"},
{q:"Perché le test suite di regressione tendono a crescere nel tempo e come si gestisce questo problema?", o:["A. Non crescono; si cancellano i vecchi test ad ogni sprint.","B. Crescono perché si aggiungono test per ogni nuova feature e ogni bug fixato. Si gestisce con la priorizzazione, l'automazione e periodica revisione per rimuovere test ridondanti o obsoleti.","C. Si risolvono aggiungendo più tester manuali.","D. Il problema si risolve ignorando i test più vecchi."], a:1, e:"La test suite di regressione cresce progressivamente. Per mantenerla gestibile: si automatizzano i test stabili, si prioritizzano (risk-based) i test da eseguire ad ogni ciclo, si rimuovono test ridondanti e si aggiornano quelli obsoleti dopo refactoring.", c:"2.3.2 Test correlati alle modifiche"},

// --- CAP 3: TEST STATICO (15 nuove) ---
{q:"Qual è la principale differenza tra una Revisione Informale e un'Ispezione Formale?", o:["A. La revisione informale è più costosa.","B. La revisione informale non ha un processo definito, ruoli formali o output documentati; l'ispezione ha un processo rigido, ruoli definiti (moderatore, autore, revisori, scribe), metriche e criteri di ingresso/uscita.","C. L'ispezione non trova difetti.","D. La revisione informale richiede più revisori."], a:1, e:"Spectrum della formalità: Informale (nessuna struttura) → Walkthrough (guidato dall'autore) → Revisione Tecnica (tra pari) → Ispezione (massima formalità con metriche, checklist e roles definiti IEEE 1028).", c:"3.2.3 Tipi di revisioni"},
{q:"Quando conviene usare una Revisione Tecnica (Technical Review) piuttosto che un'Ispezione?", o:["A. Quando si vuole massima formalità e tracciabilità.","B. Quando si vuole una valutazione tra pari tecnica (peer review) per identificare problemi tecnici e discutere alternative di design, con meno overhead burocratico rispetto a un'ispezione.","C. Quando si ha poco tempo e si vuole evitare qualsiasi documentazione.","D. Quando l'autore deve guidare la sessione."], a:1, e:"La Technical Review è condotta da colleghi tecnici con background simile. È adatta per revisioni di architettura, codice o design tecnico. Più strutturata di una revisione informale, ma meno rigida di un'ispezione: non richiede metriche obbligatorie.", c:"3.2.3 Tipi di revisioni"},
{q:"Quali sono i principali costi di una revisione e quando il costo è giustificato?", o:["A. Il costo è solo il tempo del moderatore.","B. I costi includono il tempo dei revisori, la preparazione, il meeting, il rework. È giustificato quando il costo di correggere un difetto trovato durante la revisione è significativamente inferiore al costo di trovarlo in fase di testing o in produzione.","C. Le revisioni non hanno costi significativi.","D. Il costo è giustificato solo per documenti con più di 100 pagine."], a:1, e:"Studi empirici mostrano che le revisioni hanno un ROI molto alto: trovare un difetto nei requisiti con una revisione costa frazioni del costo di trovarlo con il testing dinamico o, peggio, in produzione. Il costo del rework diminuisce drasticamente.", c:"3.1.2 Vantaggi"},
{q:"Quale delle seguenti è una metrica tipica raccolta durante un'Ispezione Formale?", o:["A. Numero di caffè consumati dai revisori.","B. Densità dei difetti trovati (difetti per pagina o per KLOC), tempo di preparazione per revisore, e tempo totale del meeting.","C. Numero di righe di codice scritte dopo la revisione.","D. Budget rimanente per il progetto."], a:1, e:"Le metriche di ispezione servono a migliorare il processo nel tempo: densità difetti per pagina (indica qualità del documento), efficienza della revisione (difetti trovati vs effort), ore di preparazione per partecipante (indica se la preparazione è adeguata).", c:"3.2.2 Processo di revisione"},
{q:"Quale fattore di successo è fondamentale per le revisioni, riguardante l'atteggiamento dei partecipanti?", o:["A. I revisori devono trovare il maggior numero di difetti possibile in modo aggressivo.","B. I revisori devono avere un mindset orientato alla qualità del prodotto, non alla critica dell'autore; i feedback devono essere costruttivi e oggettivi; l'autore deve essere aperto alla critica.","C. L'autore non dovrebbe partecipare alla sessione di revisione.","D. Solo il manager può decidere se i difetti trovati siano reali."], a:1, e:"I fattori umani sono critici nelle revisioni: clima psicologicamente sicuro, feedback incentrato sul prodotto (non sulla persona), autore ricettivo e non difensivo, revisori preparati. Le revisioni falliscono quando diventano 'caccia alle streghe'.", c:"3.2.1 Fattori di successo"},
{q:"Cos'è l'Analisi Statica (Static Analysis) e come si differenzia dalle revisioni?", o:["A. L'analisi statica è un meeting tra revisori; le revisioni usano tool automatici.","B. L'analisi statica usa strumenti automatici per esaminare il codice sorgente o altri artefatti senza eseguirli, trovando problemi come violazioni di stile, codice morto o vulnerabilità di sicurezza; le revisioni sono processi manuali o semi-manuali.","C. Sono identiche.","D. L'analisi statica richiede l'esecuzione del software."], a:1, e:"L'analisi statica (tool-based) è complementare alle revisioni (human-based): i tool trovano rapidamente pattern problematici su grandes codebase (es. SonarQube analizza migliaia di righe in secondi); le revisioni trovano problemi concettuali, di design e di comprensibilità che i tool non colgono.", c:"3.1 Fondamenti"},
{q:"Quale tipo di analisi statica esamina se tutti i percorsi del codice terminano correttamente, senza cicli infiniti o codice irraggiungibile?", o:["A. Analisi dei dati (Data Flow Analysis)","B. Analisi del flusso di controllo (Control Flow Analysis)","C. Analisi della complessità ciclomatica","D. Linting del codice"], a:1, e:"La Control Flow Analysis (CFA) costruisce il grafo del flusso di controllo del programma e lo esamina per rilevare: codice irraggiungibile (dead code), cicli infiniti potenziali, percorsi che non ritornano un valore atteso.", c:"3.1 Fondamenti"},
{q:"Cosa rileva l'Analisi del Flusso dei Dati (Data Flow Analysis) nel testing statico?", o:["A. Quali dati vengono trasferiti tra sistemi diversi.","B. Anomalie nell'uso delle variabili: variabili usate prima di essere inizializzate, variabili definite ma mai usate (dead variables), o variabili sovrascritte prima di essere lette.","C. La velocità con cui i dati vengono processati.","D. Il numero di variabili dichiarate nel codice."], a:1, e:"La Data Flow Analysis traccia il 'ciclo di vita' delle variabili: definizione (D), uso (U), kill (K). Anomalie come definire una variabile e poi sovrascriverla senza usarla (D→D), o usare una variabile non definita (U senza D precedente), indicano probabili bug.", c:"3.1 Fondamenti"},
{q:"Un linter (es. ESLint per JavaScript, Pylint per Python) è un esempio di quale tipo di strumento?", o:["A. Strumento di test dinamico.","B. Strumento di analisi statica che controlla il codice sorgente per violazioni di stile, potenziali bug e deviazioni da best practice, senza eseguire il codice.","C. Strumento di test di performance.","D. Strumento di configurazione management."], a:1, e:"I linter sono la forma più comune di analisi statica automatizzata. Rilevano: violazioni di coding standard, potenziali bug (es. variabili non usate), problemi di formattazione. Sono integrati negli IDE e nelle pipeline CI/CD per dare feedback istantaneo agli sviluppatori.", c:"3.1 Fondamenti"},
{q:"Cosa si intende per 'Product Work Item' (prodotto di lavoro) nel contesto del test statico?", o:["A. Solo il codice sorgente del software.","B. Qualsiasi artefatto prodotto durante il ciclo di vita dello sviluppo che può essere esaminato staticamente: requisiti, user stories, design, codice sorgente, test case, script di build.","C. Il prodotto finale consegnato al cliente.","D. Il report dei difetti trovati."], a:1, e:"Il test statico si applica a qualsiasi 'work product': requisiti (verifica completezza, coerenza), user stories (criteri di accettazione), codice (analisi statica), modelli UML (review di architettura), test case (review di correttezza). Non è limitato al codice.", c:"3.1 Fondamenti"},
{q:"In quale fase del processo di revisione viene definito il 'Kick-off Meeting' e qual è il suo scopo?", o:["A. Alla fine, per chiudere la revisione.","B. All'inizio della revisione: si distribuisce il documento, si spiegano gli obiettivi e l'approccio della revisione, si assegnano i ruoli e si verifica che i criteri di ingresso siano soddisfatti.","C. Durante il rework.","D. Non esiste un kick-off nelle revisioni."], a:1, e:"Il Kick-off (o Avvio) apre il processo di revisione formale. Garantisce che tutti i partecipanti capiscano cosa devono esaminare, come registrare i problemi trovati, e qual è il criterio di completamento (Exit Criteria) della revisione.", c:"3.2.2 Processo di revisione"},
{q:"Perché è importante separare il 'logging dei difetti' dalla loro 'discussione' durante il meeting di revisione?", o:["A. Non è importante; si può discutere e registrare tutto insieme.","B. Per evitare che il meeting si trasformi in lunghe discussioni tecniche su come risolvere ogni difetto, consumando il tempo previsto. I difetti si registrano durante il meeting; la soluzione si discute in seguito.","C. Perché il moderatore non è tecnico.","D. Per risparmiare carta."], a:1, e:"Una best practice nelle ispezioni è la regola 'No-fix' durante il meeting: si identificano e registrano i difetti, ma NON si discute come correggerli. Le soluzioni sono responsabilità dell'autore nel rework successivo, evitando perdite di tempo.", c:"3.2.2 Processo di revisione"},
{q:"Quando si parla di 'revisione basata su checklist' (Checklist-based Review), cosa contiene tipicamente una buona checklist?", o:["A. Solo domande generiche applicabili a qualsiasi documento.","B. Domande specifiche per il tipo di artefatto (es. requisiti, codice, test case) derivate da errori comuni storici, best practice e standard aziendali. Ogni voce rappresenta un possibile tipo di difetto.","C. L'elenco delle persone che devono partecipare.","D. I criteri di accettazione del progetto."], a:1, e:"Una checklist per requisiti potrebbe chiedere: 'Ogni requisito è verificabile?', 'I requisiti sono non ambigui?', 'Ci sono conflitti tra requisiti?'. Una checklist per codice: 'Le variabili sono inizializzate prima dell'uso?', 'Ogni funzione ha documentazione?'.", c:"3.2.4 Tecniche di revisione"},
{q:"Qual è il ruolo del 'Scribe' (Verbalizzante) in un'ispezione formale?", o:["A. Guidare il meeting e mediare i conflitti.","B. Registrare accuratamente tutti i difetti identificati, le decisioni e le osservazioni durante la sessione di revisione.","C. Decidere se i problemi trovati siano realmente difetti.","D. Correggere i difetti trovati durante il meeting."], a:1, e:"Lo Scribe registra tutto ciò che emerge durante la revisione: numero e descrizione di ogni difetto, classificazione (tipo, severità), decisioni prese. Il verbale dello Scribe è l'output documentato ufficiale della revisione.", c:"3.2.2 Ruoli"},
{q:"Quale approccio di analisi statica esamina il codice calcolando il numero di percorsi linearmente indipendenti attraverso il codice (Complessità Ciclomatica)?", o:["A. Data Flow Analysis","B. Control Flow Analysis con Complessità Ciclomatica (McCabe)","C. Linting","D. Code Review manuale"], a:1, e:"La Complessità Ciclomatica (McCabe) misura la complessità di un modulo contando i percorsi linearmente indipendenti: CC = E - N + 2P (archi - nodi + 2). Un valore alto (es. > 10) indica codice difficile da testare e manutenere, suggerendo refactoring.", c:"3.1 Fondamenti"},

// --- CAP 4: TECNICHE DI TEST (35 nuove) ---
{q:"Nel Partizionamento di Equivalenza (EP), cosa rappresenta una 'classe di equivalenza non valida'?", o:["A. Una classe che contiene valori errati inseriti dal tester.","B. Un insieme di valori di input che il sistema dovrebbe rifiutare o gestire come errori (es. caratteri non numerici in un campo numerico, valori fuori range).","C. Una classe che il sistema non elabora.","D. I valori di confine della partizione."], a:1, e:"Le classi non valide (Invalid Equivalence Partitions) sono fondamentali: testano come il sistema gestisce gli input errati. Esempio: campo età accetta 0-120. Classi non valide: <0 (numeri negativi) e >120 (troppo grande) e stringhe non numeriche. Si deve testare un valore per ogni classe non valida.", c:"4.2.1 EP"},
{q:"Perché testare un solo valore per ogni partizione di equivalenza (EP) è sufficiente in teoria?", o:["A. Perché il testing esaustivo è impossibile e bisogna scegliere.","B. Perché se il sistema elabora correttamente un valore rappresentativo della classe, si assume (per ipotesi di equivalenza) che elaborerà correttamente tutti gli altri valori della stessa classe.","C. Perché gli sviluppatori testano già tutti gli altri valori.","D. Perché le classi di equivalenza contengono sempre un solo valore."], a:1, e:"L'ipotesi di equivalenza afferma che tutti i valori di una partizione causano lo stesso comportamento del sistema. Se si trovano difetti con un valore, probabilmente altri valori della stessa classe causeranno lo stesso difetto. Ciò giustifica il test di un solo valore rappresentativo per classe.", c:"4.2.1 EP"},
{q:"Qual è la differenza tra BVA a 2 punti e BVA a 3 punti?", o:["A. Non c'è differenza, sono la stessa tecnica.","B. BVA a 2 punti testa il valore limite e il suo adiacente esterno; BVA a 3 punti testa il valore limite, il suo adiacente interno e il suo adiacente esterno, fornendo maggiore copertura dei confini.","C. BVA a 3 punti testa solo valori interni alla partizione.","D. BVA a 2 punti è per interi, BVA a 3 punti è per decimali."], a:1, e:"Esempio con limite inferiore 10: BVA 2 punti → {9, 10}; BVA 3 punti → {9, 10, 11}. La BVA a 3 punti aggiunge il valore adiacente interno (11) per verificare che il sistema accetti anche valori immediatamente dopo il limite. È più completa ma richiede più test.", c:"4.2.2 BVA"},
{q:"Applica BVA a 3 punti al seguente campo: 'Quantità ordine da 1 a 99'. Quali valori testi per il limite superiore?", o:["A. 98, 99, 100","B. 99, 100","C. 97, 99, 101","D. 0, 99, 100"], a:0, e:"Limite superiore = 99. BVA a 3 punti per il limite superiore: adiacente interno (98), il limite stesso (99), adiacente esterno (100). Si verificano: 98 (deve essere accettato), 99 (deve essere accettato), 100 (deve essere rifiutato).", c:"4.2.2 BVA"},
{q:"Cos'è il Combinatorial Testing e quando è utile?", o:["A. Un test che combina solo due variabili per volta.","B. Un approccio che testa sistematicamente combinazioni di valori di input multipli. È utile quando ci sono molte variabili di input con molti valori possibili e testare tutte le combinazioni è impraticabile.","C. Un test casuale dei valori di input.","D. Un test che combina tecniche black-box e white-box."], a:1, e:"Con N variabili, le combinazioni totali possono essere astronomiche. Il Combinatorial Testing usa tecniche come Pairwise/All-Pairs o n-wise per selezionare un sottoinsieme efficace di combinazioni che garantisce di testare ogni coppia (o n-upla) di valori almeno una volta.", c:"4.2 Tecniche di test"},
{q:"Cosa garantisce il Pairwise Testing (All-Pairs Testing)?", o:["A. Che ogni valore di ogni parametro venga testato almeno una volta.","B. Che ogni coppia di valori di parametri distinti (es. 'browser=Chrome' e 'OS=Windows') venga testata almeno una volta nella test suite.","C. Che ogni tripla di valori venga testata.","D. Che tutti i valori limite vengano testati."], a:1, e:"Il Pairwise è il caso più comune di n-wise testing con n=2. Garantisce la copertura di tutte le coppie di valori. Ricerche empiriche mostrano che la maggior parte dei difetti è causata dall'interazione di al più 2-3 variabili, quindi pairwise è molto efficiente.", c:"4.2 Tecniche di test"},
{q:"Quale tecnica white-box garantisce che ogni istruzione eseguibile nel codice sia eseguita almeno una volta?", o:["A. Decision Coverage","B. Statement Coverage (Copertura delle istruzioni)","C. MC/DC Coverage","D. Path Coverage"], a:1, e:"La Statement Coverage richiede che ogni istruzione eseguibile del codice sia stata eseguita almeno una volta dai test. Non garantisce che ogni branch sia testato: un IF senza ELSE può raggiungere 100% statement con un solo test case (quello che entra nell'IF).", c:"4.3.1 Statement Coverage"},
{q:"Cos'è la MC/DC (Modified Condition/Decision Coverage) e in quale contesto è richiesta?", o:["A. Una variante del test di regressione.","B. Una tecnica di copertura white-box che richiede che ogni condizione in una decisione mostri indipendentemente di poter influenzare l'esito della decisione. È richiesta nei sistemi safety-critical (es. avionico DO-178C, automotive IEC 26262).","C. Una tecnica black-box per sistemi embedded.","D. Una misura della complessità del codice."], a:1, e:"MC/DC va oltre la decision coverage: richiede che per ogni condizione (C1, C2... in 'C1 AND C2') ci sia almeno un test case in cui cambiare il valore di quella singola condizione cambia l'esito totale della decisione. Richiede meno test di path coverage ma è molto più rigorosa di branch coverage.", c:"4.3 White-Box"},
{q:"Quale tecnica white-box richiede che ogni percorso possibile attraverso il codice (dalla entry all'exit) venga testato?", o:["A. Statement Coverage","B. Decision Coverage","C. Path Coverage (Copertura dei percorsi)","D. Condition Coverage"], a:2, e:"La Path Coverage è la più completa (e spesso impraticabile) copertura white-box: richiede di testare ogni sequenza distinta di istruzioni dalla entry alla exit del codice. Con cicli e branch multipli, il numero di percorsi può essere infinito o astronomicamente grande.", c:"4.3 White-Box"},
{q:"Una funzione ha questo pseudocodice: IF A THEN X; IF B THEN Y; Quanti test case servono per 100% decision coverage?", o:["A. 1","B. 2","C. 4","D. 8"], a:1, e:"Ci sono 2 decisioni indipendenti (IF A, IF B). Decision coverage richiede che ogni decisione sia vera e falsa. Con 2 test case si può coprire entrambe: TC1 (A=T, B=T), TC2 (A=F, B=F). Ogni IF è stato Vero (TC1) e Falso (TC2).", c:"4.3.2 Copertura delle decisioni"},
{q:"Nello State Transition Testing, cos'è un 'test di transizione' valido rispetto a uno non valido?", o:["A. Valido = transizione che porta a uno stato finale; Non valido = transizione che porta a uno stato di errore.","B. Valido = transizione ammessa dal modello (evento che causa il cambio di stato nel flusso normale); Non valido = tentativo di transizione non prevista (evento in uno stato che non lo consente).","C. Non esiste la distinzione tra transizioni valide e non valide.","D. Valido = testato dal tester; Non valido = non testato."], a:1, e:"Le transizioni non valide (invalid transitions) sono importanti da testare per la robustezza: es. cercare di 'Pagare' un ordine che è già nello stato 'Spedito'. Il sistema dovrebbe gestire gracefully queste situazioni (messaggio di errore, nessun cambio di stato).", c:"4.2.4 State Transition"},
{q:"Cos'è lo 'Scenario-based Testing' (Test basato su scenari)?", o:["A. Un test che verifica un singolo requisito in isolamento.","B. Un approccio che testa il sistema attraverso sequenze realistiche di interazioni utente-sistema (scenari d'uso), simulando come un utente reale userebbe il software per raggiungere un obiettivo.","C. Un sinonimo di use case testing.","D. Un test basato su errori comuni."], a:1, e:"Il scenario-based testing cattura flussi reali d'uso: es. 'Utente cerca prodotto → aggiunge al carrello → applica coupon → paga → riceve conferma'. Ogni scenario testa più funzionalità in interazione, trovando difetti che i test isolati non trovano.", c:"4.2.5 Use Case Testing"},
{q:"Nel BDD, cosa rappresenta lo scenario 'Given un utente autenticato / When clicca su Logout / Then viene reindirizzato alla pagina login e la sessione viene terminata'?", o:["A. Un requisito funzionale scritto in prosa.","B. Un test case eseguibile scritto in linguaggio Gherkin che descrive il comportamento atteso del sistema da una prospettiva utente, leggibile da tutti gli stakeholder.","C. Un test case white-box.","D. Una storia utente (User Story)."], a:1, e:"Questo è un test Gherkin/BDD: Given (precondizione: utente autenticato), When (azione: clicca Logout), Then (risultato atteso: redirect a login + sessione terminata). Può essere automatizzato con framework come Cucumber, SpecFlow o Behave.", c:"2.1.1 BDD"},
{q:"Qual è il principale vantaggio delle checklist nel testing dell'accessibilità (Accessibility Testing)?", o:["A. Automatizzano completamente i test di accessibilità.","B. Forniscono un elenco sistematico di criteri standard (es. WCAG 2.1) da verificare, garantendo che nessun aspetto critico (es. contrasto colori, testi alternativi per immagini, navigabilità da tastiera) venga tralasciato.","C. Sostituiscono la necessità di testare con utenti reali con disabilità.","D. Sono più veloci della BVA."], a:1, e:"Le checklist per l'accessibilità basate su WCAG (Web Content Accessibility Guidelines) includono criteri come: testi alternativi per immagini (WCAG 1.1.1), contrasto cromatico minimo (WCAG 1.4.3), focus da tastiera visibile (WCAG 2.4.7). Garantiscono copertura sistematica degli standard.", c:"4.4.3 Checklist-based testing"},
{q:"Quale delle seguenti è la differenza tra 'Error Guessing' e 'Test Esplorativo'?", o:["A. Sono identici.","B. L'Error Guessing usa l'esperienza per predire specifici tipi di difetti e creare test case mirati per trovarli; il Testing Esplorativo è un approccio simultaneo di progettazione-esecuzione-apprendimento guidato da un charter, senza test case predefiniti.","C. Il Test Esplorativo richiede più esperienza.","D. L'Error Guessing non è riconosciuto dall'ISTQB."], a:1, e:"Error Guessing: il tester usa la sua esperienza per elencare errori tipici (es. divisione per zero, null pointer, date di febbraio con anni bisestili) e crea test case specifici. Exploratory Testing: il tester esplora il sistema liberamente, imparando man mano e dirigendo i test in base a ciò che trova.", c:"4.4 Tecniche basate sull'esperienza"},
{q:"Cosa si intende per 'Test Charter' nel Test Esplorativo?", o:["A. Un documento formale di pianificazione del test.","B. Un'istruzione breve che definisce l'obiettivo e il perimetro di una sessione di test esplorativo (es. 'Esplora il modulo di pagamento per trovare problemi con carte di credito internazionali').","C. L'elenco di tutti i test case da eseguire.","D. Il contratto tra il cliente e il team di testing."], a:1, e:"Il Test Charter (o Mission Statement) guida la sessione esplorativa senza prescrivere i test step-by-step. Definisce: cosa esplorare, con quale obiettivo, in quanto tempo. Bilancia libertà e struttura nel testing esplorativo.", c:"4.4.2 Test Esplorativo"},
{q:"Quante regole (colonne) ha una Decision Table con 4 condizioni booleane in forma completa?", o:["A. 4","B. 8","C. 16","D. 32"], a:2, e:"Con N condizioni booleane (Vero/Falso), la tabella completa ha 2^N colonne (regole). Con 4 condizioni: 2^4 = 16 regole. Spesso si semplifica collassando regole con lo stesso output e condizioni 'don't care' (–) irrilevanti.", c:"4.2.3 Decision Table"},
{q:"In una Decision Table, cosa significa il simbolo '-' (trattino) in una cella di condizione?", o:["A. La condizione non è applicabile a questa regola (Don't care): il valore della condizione non influenza l'output.","B. La condizione è falsa.","C. La condizione è vera.","D. La condizione è un errore."], a:0, e:"Il simbolo '-' (Don't care) indica che il valore di quella condizione è irrilevante per quella regola: l'output è lo stesso indipendentemente dal valore di quella condizione. Permette di comprimere più regole in una, riducendo le colonne della tabella.", c:"4.2.3 Decision Table"},
{q:"Qual è il limite principale dello Statement Coverage rispetto alla Decision Coverage?", o:["A. La statement coverage è più difficile da misurare.","B. La statement coverage non garantisce che ogni branch (ramo) di una decisione sia stato testato: un IF senza ELSE raggiunge 100% statement con un test ma non copre il caso in cui la condizione è falsa.","C. La statement coverage richiede più test case.","D. La statement coverage non è riconosciuta dall'ISTQB."], a:1, e:"Esempio: IF (x > 0) { doSomething(); }. Con x=5, si raggiunge 100% statement coverage (doSomething() eseguita). Ma il caso x<=0 (IF falso) non è testato. La decision coverage richiederebbe anche un test con x<=0 per coprire il branch 'falso' implicito.", c:"4.3 Coverage"},
{q:"Nel testing White-Box, cosa misura la 'Branch Coverage' (Copertura dei rami)?", o:["A. Il numero di file sorgente testati.","B. La percentuale di rami del codice (true/false per ogni decisione, ogni caso di un switch) esercitati dai test.","C. La percentuale di requisiti coperti dai test.","D. Il numero di bug trovati per modulo."], a:1, e:"Branch Coverage = Decision Coverage: richiede che ogni ramo (sia True sia False) di ogni decisione sia eseguito almeno una volta. La formula è: (Rami eseguiti / Totale rami) × 100%. Raggiungere 100% branch coverage implica automaticamente 100% statement coverage.", c:"4.3.2 Copertura delle decisioni"},
{q:"Cosa distingue le tecniche 'Black-Box' dalle tecniche 'White-Box'?", o:["A. Il colore del computer usato per eseguire i test.","B. Black-Box: i test derivano dalle specifiche esterne (requisiti, comportamento atteso) senza conoscere la struttura interna del codice; White-Box: i test derivano dalla struttura interna del codice (istruzioni, branch, percorsi).","C. Black-Box è solo manuale; White-Box è solo automatizzato.","D. Black-Box verifica la sicurezza; White-Box verifica la funzionalità."], a:1, e:"Tecniche Black-Box (EP, BVA, Decision Table, State Transition, Use Case) derivano i test dalle specifiche. Tecniche White-Box (Statement Coverage, Branch Coverage, MC/DC) derivano i test dalla struttura del codice. Entrambe sono complementari e usate insieme per una copertura completa.", c:"4.1 Tecniche di test"},
{q:"Cosa si verifica con il 'Path Testing'?", o:["A. La correttezza del percorso di navigazione nella UI.","B. Che ogni percorso di esecuzione distinto attraverso il codice (dalla entry alla exit) sia stato testato almeno una volta.","C. La velocità con cui i dati percorrono il sistema.","D. I percorsi di comunicazione tra sistemi diversi."], a:1, e:"Il Path Testing è la forma più completa di white-box testing: richiede di percorrere ogni sequenza di istruzioni dalla entry alla exit. Con cicli, i percorsi possono essere infiniti; si usa quindi la Complessità Ciclomatica di McCabe per definire il set minimo di percorsi linearmente indipendenti.", c:"4.3 White-Box"},
{q:"Qual è il vantaggio del Test Esplorativo rispetto ai test scriptati formali?", o:["A. È sempre più veloce e trova più bug.","B. È particolarmente efficace per scoprire difetti non previsti, testare nuove aree sconosciute, e verificare l'usabilità in modo naturale; si adatta dinamicamente in base a ciò che il tester trova.","C. Non richiede alcuna competenza tecnica.","D. Può essere completamente automatizzato."], a:1, e:"Il testing esplorativo eccelle dove i test scriptati falliscono: nelle aree sconosciute, nei difetti 'creativi' che nessuno aveva immaginato, nelle sessioni di testing in ambienti Agile dove i requisiti evolvono rapidamente. Il tester usa intuizione ed esperienza in tempo reale.", c:"4.4.2 Test Esplorativo"},
{q:"Come vengono tipicamente derivati i test case dalla tecnica delle Decision Table?", o:["A. Un test case per ogni riga della tabella (condizione).","B. Un test case per ogni colonna/regola della tabella, impostando i valori delle condizioni secondo quella regola e verificando che l'azione/output risultante corrisponda a quello atteso.","C. Un test case per ogni cella della tabella.","D. Un solo test case che copre tutte le regole."], a:1, e:"Ogni colonna della Decision Table rappresenta una regola (combinazione di condizioni → azione). Un test case corrisponde a una regola: si impostano gli input (condizioni) come indicato nella colonna e si verifica che il sistema produca l'output (azione) specificato.", c:"4.2.3 Decision Table"},
{q:"Quale tecnica è più adatta per testare un sistema con un numero elevato di parametri di configurazione con diversi valori possibili ciascuno?", o:["A. Boundary Value Analysis","B. Decision Table Testing","C. Pairwise Testing (All-Pairs)","D. State Transition Testing"], a:2, e:"Con 10 parametri ognuno con 3 valori possibili, le combinazioni totali sono 3^10 = 59.049. Il Pairwise Testing riduce drasticamente il numero di test necessari (spesso a poche decine o centinaia) garantendo che ogni coppia di parametri-valori sia coperta almeno una volta.", c:"4.2 Tecniche di test"},
{q:"In ATDD, chi partecipa alla definizione dei test di accettazione?", o:["A. Solo i tester.","B. Solo gli sviluppatori.","C. Il trio formato da business analyst/PO, sviluppatori e tester che collaborano insieme (Three Amigos) per definire i criteri di accettazione prima dello sviluppo.","D. Solo il cliente."], a:2, e:"Il 'Three Amigos Meeting' (o Discovery Workshop) è il cuore dell'ATDD: le tre prospettive (business: COSA, dev: COME, test: COSA POTREBBE ANDARE STORTO) definiscono insieme scenari di test che diventeranno i criteri di accettazione. Questo riduce malintesi e difetti sin dall'inizio.", c:"2.1.1 ATDD"},
{q:"Cosa succede nel BDD quando i test Gherkin (Given/When/Then) vengono automatizzati con un framework come Cucumber?", o:["A. Il codice viene generato automaticamente senza intervento umano.","B. Le frasi Gherkin vengono associate (tramite step definitions) a codice eseguibile: il framework esegue i test e verifica automaticamente che il comportamento del sistema corrisponda a quello descritto negli scenari.","C. I test diventano documenti statici non eseguibili.","D. I test vengono eseguiti solo manualmente."], a:1, e:"Cucumber (e framework simili) legge i file .feature (Gherkin), per ogni step (Given, When, Then) cerca una step definition (funzione di codice corrispondente), la esegue, e riporta Pass/Fail. I test Gherkin diventano documentazione viva e eseguibile simultaneamente.", c:"2.1.1 BDD"},
{q:"Perché le tecniche basate sull'esperienza (Error Guessing, Exploratory Testing, Checklist) sono considerate complementari alle tecniche formali (EP, BVA, Decision Table)?", o:["A. Perché le tecniche formali trovano troppi falsi positivi.","B. Perché le tecniche formali derivano i test sistematicamente dalle specifiche ma potrebbero non coprire scenari inattesi, errori di usabilità o difetti creativi che solo l'esperienza umana e l'intuizione del tester possono scoprire.","C. Le tecniche basate sull'esperienza sono superiori e sostituiscono le formali.","D. Non sono complementari; si usa solo un tipo alla volta."], a:1, e:"Un approccio ottimale combina entrambi: le tecniche formali garantiscono copertura sistematica delle specifiche; le tecniche basate sull'esperienza aggiungono la capacità di trovare difetti 'creativi', di usabilità e casi d'uso reali non catturati dai requisiti formali.", c:"4.4 Tecniche basate sull'esperienza"},
{q:"In EP, una stessa variabile può avere più partizioni valide contemporaneamente?", o:["A. No, c'è sempre una sola partizione valida.","B. Sì, è possibile avere più partizioni valide se il sistema deve gestire diversi set di valori validi in modo diverso (es. uno sconto del 5% per ordini 50-99€ e del 10% per ordini 100-199€ sono due partizioni valide distinte).","C. Le partizioni valide e non valide sono sempre in numero uguale.","D. EP si applica solo a variabili numeriche."], a:1, e:"Se il sistema applica logica diversa a sottoinsiemi diversi di valori accettati, questi formano partizioni valide distinte: ciascuna deve essere testata con un valore rappresentativo. Esempio: sistema di scoring con classi 0-59 (bocciato), 60-79 (sufficiente), 80-100 (ottimo) → 3 partizioni valide.", c:"4.2.1 EP"},
{q:"Qual è il concetto di 'Test Condition' e come si distingue da 'Test Case'?", o:["A. Sono sinonimi.","B. Una Test Condition è un aspetto testabile ad alto livello derivato dall'analisi (es. 'Login con credenziali errate'); un Test Case è la specifica dettagliata di come testarlo (input precisi, passi, dati, risultato atteso, precondizioni).","C. Una Test Condition è più dettagliata di un Test Case.","D. I Test Case derivano dai Test Data, non dalle Test Condition."], a:1, e:"La gerarchia ISTQB: Test Basis → Test Conditions (analisi) → Test Cases (progettazione) → Test Procedures/Scripts (implementazione). Una Test Condition può dare origine a uno o più Test Case; ogni Test Case specifica esattamente come eseguire la verifica.", c:"1.4 Processo di test"},
{q:"Quando si usa la State Transition Testing, cosa descrive una 'State Table' (Tabella degli stati)?", o:["A. Una lista di tutti gli stati del sistema.","B. Una matrice che mostra per ogni stato (righe) e per ogni possibile evento (colonne) il risultato: lo stato successivo o l'azione eseguita. Evidenzia anche le transizioni non valide.","C. Un diagramma UML con frecce e stati.","D. L'elenco degli stati finali accettabili."], a:1, e:"La State Table (o tabella delle transizioni) è la rappresentazione tabellare del diagramma a stati. Le righe sono gli stati attuali, le colonne sono gli eventi. Ogni cella mostra lo stato successivo e/o l'azione. Le celle vuote o con 'errore' rappresentano transizioni non valide.", c:"4.2.4 State Transition"},
{q:"Cosa si intende per 'Test Condition Coverage' (Copertura delle condizioni di test)?", o:["A. La percentuale di condizioni booleane in ogni decisione che sono state valutate sia True che False.","B. La percentuale di test condition identificate che sono state coperte (esercitate) dai test case eseguiti.","C. La percentuale di statement coverage raggiunta.","D. Il numero di test case eseguiti su quelli pianificati."], a:1, e:"La Test Condition Coverage misura quanto delle Test Conditions identificate durante l'analisi è stata effettivamente verificata dall'esecuzione dei test. Formula: (Test Conditions coperte / Totale Test Conditions identificate) × 100%.", c:"4.1 Tecniche di test"},
{q:"Come si calcola la 'Decision Coverage' (Branch Coverage) per un modulo con 5 decisioni IF-THEN-ELSE?", o:["A. (Decisioni testate / Totale decisioni) × 100%","B. (Rami eseguiti / Totale rami) × 100% — con 5 IF-THEN-ELSE ci sono 10 rami totali (True+False per ogni IF).","C. (Istruzioni eseguite / Totale istruzioni) × 100%","D. Il numero di test case eseguiti."], a:1, e:"Ogni decisione IF-THEN-ELSE ha 2 rami (True e False). Con 5 decisioni: 10 rami totali. Se i test eseguiti coprono 8 rami su 10: Decision Coverage = 8/10 × 100% = 80%. Per raggiungere 100%, ogni IF deve essere testato sia come vero sia come falso.", c:"4.3.2 Copertura delle decisioni"},
{q:"Quale tecnica è particolarmente utile per testare sistemi in cui l'ordine degli eventi è importante (es. protocolli di rete, flussi di lavoro)?", o:["A. Boundary Value Analysis","B. Equivalence Partitioning","C. State Transition Testing","D. Decision Table Testing"], a:2, e:"Lo State Transition Testing è ideale per sistemi che si comportano diversamente in base alla loro storia (stato corrente). Un protocollo TCP, un processo di ordine e-commerce, o un ATM hanno comportamenti dipendenti dallo stato. ST cattura questa dipendenza temporale.", c:"4.2.4 State Transition"},

// --- CAP 5: GESTIONE DEL TEST (20 nuove) ---
{q:"Qual è il ciclo di vita tipico di un difetto (Defect Lifecycle)?", o:["A. Trovato → Risolto → Chiuso.","B. New → Assigned → In Progress (sviluppatore analizza/corregge) → Fixed → In Verification (tester ri-testa) → Closed (se risolto) oppure Reopened (se non risolto).","C. Aperto → Chiuso → Rifiutato.","D. Segnalato → Ignorato → Dimenticato."], a:1, e:"Il Defect Lifecycle gestisce il flusso di un difetto: New (appena trovato) → Assigned (assegnato a uno sviluppatore) → In Progress (in correzione) → Fixed (corretto) → In Verification (il tester esegue il confirmation test) → Closed o Reopened. Possibili stati extra: Rejected (non è un bug), Deferred (posticipato).", c:"5.6 Gestione difetti"},
{q:"Un bug di sicurezza che espone dati sensibili degli utenti ha alta severità ma bassa priorità di risoluzione immediata secondo il PM. Come si chiama questo scenario?", o:["A. Non può accadere: alta severità implica sempre alta priorità.","B. Disallineamento tra Severità e Priorità: la Severità (impatto tecnico) è alta, ma la Priorità (urgenza di fix per il business) è valutata bassa per motivazioni di business (es. il bug è in una feature non ancora rilasciata).","C. Il PM ha ragione; la sicurezza non è mai urgente.","D. Il tester ha sbagliato la severità."], a:1, e:"Severità e Priorità possono divergere: Alta Severità / Bassa Priorità (es. crash in funzione poco usata, non urgente). Bassa Severità / Alta Priorità (es. errore grammaticale nel logo dell'app, danno d'immagine, fix immediato). La decisione di priorità è del business/PM, non del tester.", c:"5.6 Gestione difetti"},
{q:"Cos'è il 'Defect Density' (Densità dei difetti) come KPI del testing?", o:["A. Il numero totale di bug trovati nel progetto.","B. Il numero di difetti trovati per unità dimensionale del software (es. difetti per KLOC o per Function Point), usato per confrontare la qualità tra moduli o progetti.","C. La velocità con cui i tester trovano difetti.","D. Il peso medio dei bug report."], a:1, e:"Defect Density = Numero difetti / Dimensione software (es. KLOC). Alta densità in un modulo indica qualità bassa o alta complessità. Permette confronti tra progetti e moduli, e identifica i 'hot spot' dove concentrare testing e refactoring.", c:"5.3 Monitoraggio e controllo"},
{q:"Cos'è il 'Defect Detection Percentage' (DDP) e perché è importante?", o:["A. La percentuale di difetti trovati durante il test rispetto al numero totale di bug report.","B. La percentuale di difetti trovati dal processo di testing rispetto al totale dei difetti presenti (inclusi quelli sfuggiti in produzione). Alta DDP indica un processo di test efficace.","C. Il numero di difetti trovati rispetto al budget speso.","D. Il ritmo di scoperta dei difetti per sprint."], a:1, e:"DDP = Difetti trovati in test / (Difetti trovati in test + Difetti sfuggiti in produzione) × 100%. Se trovi 90 bug in test e ne sfuggono 10 in produzione, DDP = 90/(90+10) = 90%. È la misura fondamentale dell'efficacia del testing.", c:"5.3 Monitoraggio e controllo"},
{q:"Qual è il 'Test Pass Rate' come metrica di avanzamento?", o:["A. La velocità con cui i tester eseguono i test.","B. La percentuale di test case eseguiti che hanno dato esito Passed rispetto al totale eseguito. Un basso Pass Rate indica molti difetti o test instabili.","C. Il numero di test superati rispetto al budget.","D. La percentuale di test automatici nel totale della test suite."], a:1, e:"Test Pass Rate = Test Passati / Test Eseguiti × 100%. Se ho eseguito 100 test e 85 passano: Pass Rate = 85%. Monitorare il trend nel tempo (es. sprint su sprint) mostra se la qualità migliora. Un Pass Rate in calo avvisa problemi.", c:"5.3 Monitoraggio e controllo"},
{q:"Cos'è una 'Test Dashboard' e qual è il suo scopo principale?", o:["A. Un pannello di controllo dell'aereo durante il testing.","B. Una rappresentazione visuale (cruscotto) dello stato corrente del testing: metriche chiave (pass rate, bug aperti, copertura), trend, e semafori di rischio. Supporta decisioni rapide e comunicazione con gli stakeholder.","C. Un tool per l'automazione dei test.","D. Un documento formale inviato al cliente."], a:1, e:"Le dashboard di test mostrano KPI in tempo reale: test eseguiti/totali, pass/fail rate, bug per severità, burn-down chart. Sono fondamentali per il Test Monitoring: permettono al Test Manager e agli stakeholder di capire 'dove siamo' con un colpo d'occhio.", c:"5.3 Monitoraggio e controllo"},
{q:"Cos'è una 'Retrospettiva' (Retrospective) in Agile e qual è la sua utilità per il testing?", o:["A. Un meeting in cui si pianifica il prossimo sprint.","B. Una cerimonia Agile (al termine di ogni sprint) in cui il team riflette su cosa è andato bene, cosa è andato male e cosa migliorare. Per il testing: si analizzano difetti sfuggiti, inefficienze nel processo, tool da adottare.","C. Un report inviato al management.","D. Una revisione tecnica del codice."], a:1, e:"La retrospettiva è il motore del miglioramento continuo in Agile (Kaizen). Per il testing: si discutono difetti sfuggiti (perché non trovati?), test instabili (flaky tests), tempo eccessivo di esecuzione, coverage gap. Le azioni definite migliorano il processo nello sprint successivo.", c:"5.2 Test Planning"},
{q:"Cosa si intende per 'Product Risk Analysis' nel contesto del testing?", o:["A. L'analisi dei rischi finanziari del prodotto.","B. L'identificazione e valutazione dei rischi di prodotto (aree del software che potrebbero non funzionare) per prioritizzare le attività di test: si testa di più dove il rischio (probabilità × impatto) è più alto.","C. Un'analisi del competitor.","D. La revisione dei requisiti di prodotto."], a:1, e:"La Product Risk Analysis guida il Risk-based Testing: 1) Identificare le aree a rischio (es. modulo di pagamento, autenticazione), 2) Valutare probabilità di difetti e impatto del fallimento, 3) Prioritizzare testing intensivo sulle aree ad alto rischio. Massimizza l'efficacia con le risorse disponibili.", c:"5.5 Rischio"},
{q:"Cos'è la 'Test Closure' (Chiusura del test) e cosa include?", o:["A. La cancellazione di tutti i test case al termine del progetto.","B. L'ultima fase del processo di test che include: valutazione dei criteri di uscita, produzione del Test Summary Report, archiviazione degli artefatti di test, chiusura dei bug report, e analisi delle lezioni apprese.","C. La chiusura dell'account del tool di test management.","D. Il meeting in cui si annunciano i risultati al cliente."], a:1, e:"La Test Closure garantisce che tutto sia documentato per il futuro: il Test Summary Report riassume i risultati, gli artefatti (test case, dati, script) vengono archiviati per riuso, i difetti vengono aggiornati, e le lezioni apprese alimentano il processo di miglioramento continuo.", c:"5.7 Test Closure"},
{q:"Come si calcola il 'Livello di Rischio' in un'analisi risk-based?", o:["A. Livello di Rischio = Numero di difetti trovati.","B. Livello di Rischio = Probabilità che il rischio si materializzi × Impatto se si materializza.","C. Livello di Rischio = Severità del bug × Priorità.","D. Livello di Rischio = Effort di test × Costo."], a:1, e:"La formula Risk Level = Likelihood × Impact è il fondamento del Risk-based Testing. Un'area con alta probabilità di difetti e alto impatto di business ottiene il massimo Livello di Rischio e viene testata prima e più intensivamente. Aree a basso rischio ricevono meno testing.", c:"5.5 Rischio"},
{q:"Qual è la differenza tra un 'Rischio di Progetto' e un 'Rischio di Prodotto'?", o:["A. Non c'è differenza.","B. Rischio di Progetto: eventi che mettono a rischio il raggiungimento degli obiettivi del progetto (es. risorse insufficienti, scadenze a rischio). Rischio di Prodotto: possibilità che il prodotto non soddisfi le aspettative degli stakeholder o abbia difetti (es. crash in produzione).","C. Rischio di Progetto riguarda solo il budget; Rischio di Prodotto riguarda solo la UI.","D. Il Rischio di Prodotto è sempre più grave del Rischio di Progetto."], a:1, e:"Esempi Rischio di Progetto: budget insufficiente, tester non disponibili, ambiente di test non pronto. Esempi Rischio di Prodotto: modulo di sicurezza con difetti, performance insufficiente, dati corrotti. Entrambi devono essere monitorati e mitigati durante il progetto.", c:"5.5 Rischio"},
{q:"Quale delle seguenti è una 'Exit Criteria' (Criterio di Uscita) tipica per il System Testing?", o:["A. Tutti i requisiti funzionali sono stati scritti.","B. La copertura dei test ha raggiunto il livello pianificato (es. 95%), nessun difetto critico o bloccante è aperto, e il Test Summary Report è stato approvato.","C. Il budget per il testing è esaurito.","D. Tutti gli sviluppatori hanno completato il codice."], a:1, e:"I criteri di uscita definiscono quando una fase di test è sufficientemente completata da poter passare alla successiva (o al rilascio). Tipici exit criteria: % copertura raggiunta, zero bug Critical/Blocker aperti, trend dei bug stabile o in miglioramento, report approvato.", c:"5.2.3 Entry/Exit criteria"},
{q:"Cos'è il 'Test Summary Report' e a chi è destinato?", o:["A. Un elenco dei test eseguiti, destinato solo ai tester.","B. Un documento che riassume le attività di test effettuate, le metriche (test eseguiti, pass/fail, bug trovati/chiusi), la valutazione della qualità del software, i rischi residui e la raccomandazione sul rilascio. Destinato al management e agli stakeholder.","C. Il codice sorgente degli script di test.","D. Il piano per il prossimo ciclo di test."], a:1, e:"Il Test Summary Report è il documento formale di chiusura del test: dice 'ecco cosa abbiamo fatto, ecco i risultati, ecco i rischi residui, ecco la nostra raccomandazione (rilasciare o no)'. È lo strumento principale di comunicazione del testing al management.", c:"5.7 Test Closure"},
{q:"Perché il 'Risk Mitigation' (Mitigazione del rischio) è parte integrante del processo di test?", o:["A. La mitigazione del rischio non è responsabilità del testing.","B. Il testing stesso è una forma di mitigazione del rischio: rilevare difetti prima del rilascio riduce la probabilità che si verifichino failure in produzione e ne riduce l'impatto. Le strategie di testing (copertura, tecniche usate) sono scelte di mitigazione del rischio.","C. La mitigazione del rischio riguarda solo la sicurezza IT.","D. Si mitiga il rischio solo aumentando il numero di tester."], a:1, e:"Il risk-based testing alloca lo sforzo per massimizzare la riduzione del rischio: testare le aree ad alto rischio con maggiore intensità riduce la probabilità di failure critici in produzione. Il testing è per definizione un'attività di controllo e mitigazione del rischio.", c:"5.5 Rischio"},
{q:"Cosa descrive la metrica 'Burn-down chart' nel contesto del testing Agile?", o:["A. Un grafico che mostra il numero di sviluppatori nel team.","B. Un grafico che mostra il lavoro rimanente (es. test case da eseguire, bug da chiudere) rispetto al tempo, permettendo di vedere se il team è in linea con il piano dello sprint.","C. Un report di fine progetto.","D. Il numero di bug trovati per giorno."], a:1, e:"Il Test Burn-down Chart mostra: asse X (giorni dello sprint), asse Y (test rimanenti o story points rimanenti). La linea ideale va da 'tutto il lavoro' a 'zero' in modo lineare. Se la linea reale è sopra quella ideale, il team è in ritardo. Strumento visuale fondamentale per il monitoring.", c:"5.3 Monitoraggio e controllo"},
{q:"Qual è il ruolo dell'Analisi di Impatto (Impact Analysis) nella gestione del testing durante la manutenzione?", o:["A. Analizzare l'impatto economico del testing sul progetto.","B. Determinare quali aree del sistema possono essere influenzate da una modifica al codice o ai requisiti, per decidere l'ampiezza dei test di regressione necessari ed evitare sia test insufficienti che eccessivi.","C. Misurare l'impatto dei difetti sugli utenti.","D. Calcolare quanti tester servono per un progetto."], a:1, e:"L'Impact Analysis risponde a: 'Questa modifica può rompere altro?' Se si modifica il modulo pagamento, l'analisi potrebbe identificare che sono a rischio anche il modulo ordini e il modulo email. Si eseguiranno quindi test di regressione specifici per quelle aree.", c:"5.5 Rischio"},
{q:"In un contesto Agile, come si gestisce il Test Plan?", o:["A. Si scrive un Test Plan completo e dettagliato all'inizio e non si modifica mai.","B. Il Test Plan può essere un documento leggero e evolutivo (es. una sezione nella Definition of Done, una Test Strategy ad alto livello), aggiornato sprint per sprint man mano che il progetto evolve.","C. In Agile non si fa mai Test Planning.","D. Il Test Plan è responsabilità esclusiva del Product Owner."], a:1, e:"In Agile, il Test Planning avviene a più livelli: un piano di release ad alto livello (cosa si testerà nella release) e un piano per ogni sprint (cosa si testerà in questo sprint). È più flessibile e iterativo del Test Plan waterfall, adattandosi ai cambiamenti frequenti.", c:"5.2 Test Planning"},
{q:"Quale delle seguenti informazioni NON è tipicamente inclusa in un Defect Report (Bug Report)?", o:["A. Passi per riprodurre il difetto.","B. Il reddito annuale del tester che ha trovato il bug.","C. Severità e priorità del difetto.","D. Screenshot o evidenza del fallimento."], a:1, e:"Un Defect Report ben formato include: ID univoco, titolo descrittivo, ambiente (OS, browser, versione), passi per riprodurre, risultato atteso, risultato effettivo, severità, priorità, screenshot/log, e eventualmente la versione del software. Il reddito del tester è irrilevante.", c:"5.6 Gestione difetti"},
{q:"Cosa si intende per 'Flaky Test' (test instabile) e perché è problematico?", o:["A. Un test che trova difetti gravi.","B. Un test che produce risultati non deterministici (a volte passa, a volte fallisce) senza che il codice sia cambiato. È problematico perché erode la fiducia nella test suite, causa falsi allarmi e spreca tempo nell'investigazione.","C. Un test scritto male che va riscritto.","D. Un test di performance che varia in base al carico."], a:1, e:"I Flaky Test sono uno dei problemi più comuni nelle test suite automatizzate. Cause tipiche: dipendenze da timing (race condition), ordine di esecuzione dei test, dati di test condivisi, dipendenze da servizi esterni. Vanno eliminati o isolati perché danneggiano la credibilità dell'automazione.", c:"5.3 Monitoraggio e controllo"},
{q:"Nella gestione dei difetti, cosa significa che un bug viene 'Deferred' (posticipato)?", o:["A. Il bug è stato corretto e rilasciato.","B. Il bug è stato confermato ma la sua correzione viene deliberatamente posticipata a una release futura, di solito per decisione del product owner o del management (bassa priorità o non abbastanza tempo in questo sprint).","C. Il bug è stato duplicato.","D. Il bug è stato rifiutato perché non è reale."], a:1, e:"Deferred indica che il difetto è reale e confermato, ma non verrà corretto nella release corrente. Motivazioni: bassa priorità, effort di fix troppo alto per il beneficio, la feature verrà ridisegnata, o semplicemente mancano risorse nel sprint corrente.", c:"5.6 Gestione difetti"},

// --- CAP 6: STRUMENTI (10 nuove) ---
{q:"Come si integra il testing automatico in una pipeline CI/CD?", o:["A. I test automatici vengono eseguiti manualmente a fine pipeline.","B. I test vengono eseguiti automaticamente ad ogni commit/push: prima i test veloci (unit test), poi integration test, poi regression test. Un fallimento blocca la pipeline (fail fast) e notifica il team immediatamente.","C. La pipeline CI/CD non supporta il testing.","D. I test automatici vengono eseguiti solo in produzione."], a:1, e:"Una pipeline CI/CD ben strutturata ha stadi di test progressivi: 1) Unit/Component Test (secondi), 2) Integration Test (minuti), 3) Regression/E2E Test (minuti-ore), 4) Performance/Security Test (ore). Ogni stadio deve passare prima di procedere al successivo. I test veloci girano ad ogni commit; i test lunghi girano notturno.", c:"6.1.1 Strumenti"},
{q:"Quali sono i principali vantaggi dell'automazione dei test di regressione?", o:["A. Elimina completamente la necessità del testing manuale.","B. Riduce il tempo e l'effort di esecuzione dei test di regressione ripetitivi, aumenta la frequenza con cui possono essere eseguiti (ad ogni build), migliora la coerenza (nessuna variazione umana) e libera i tester per attività esplorative ad alto valore.","C. L'automazione è sempre più economica del testing manuale.","D. Garantisce di trovare tutti i difetti."], a:1, e:"L'automazione eccelle nei test stabili, ripetitivi e a basso cambiamento (es. regression suite). Vantaggi: esecuzione 24/7 senza fatica, velocità, coerenza, integrazione CI/CD. Non sostituisce il testing manuale per test esplorativi, usabilità e scenari nuovi.", c:"6.2 Rischi e Benefici"},
{q:"Come si calcola il ROI (Return on Investment) dell'automazione dei test?", o:["A. ROI = Numero di test automatizzati / Numero di tester.","B. ROI = (Costi risparmiati grazie all'automazione - Costi dell'automazione) / Costi dell'automazione × 100%. Considerando: costo di sviluppo degli script, manutenzione, tool license vs risparmio sull'execution manuale ripetuta.","C. ROI = Bug trovati dall'automazione / Bug totali.","D. Il ROI dell'automazione non è misurabile."], a:1, e:"Il ROI dell'automazione migliora nel tempo: i costi fissi (sviluppo script, tool) si ammortizzano su molte esecuzioni. Esempio: uno script costa 8h per scrivere ma risparmia 2h di testing manuale per ogni build. Dopo 4 build si è in pareggio; da lì in poi è puro risparmio.", c:"6.2 Rischi e Benefici"},
{q:"Quale tipo di strumento viene usato specificamente per il Performance Testing (test di performance)?", o:["A. Selenium WebDriver","B. JMeter, Gatling o LoadRunner — strumenti che simulano carichi elevati di utenti virtuali per misurare tempi di risposta, throughput e stabilità del sistema sotto stress.","C. SonarQube","D. Cucumber"], a:1, e:"Strumenti di performance testing (JMeter open source, LoadRunner commerciale, Gatling) simulano N utenti concorrenti inviando richieste HTTP (o altri protocolli) e misurano: response time, throughput (req/sec), error rate, utilizzo risorse (CPU, RAM). Essenziali per load test, stress test e endurance test.", c:"6.1.1 Strumenti"},
{q:"Quale tipo di strumento viene usato per il Security Testing automatizzato (DAST - Dynamic Application Security Testing)?", o:["A. Selenium","B. Tool come OWASP ZAP o Burp Suite che analizzano l'applicazione in esecuzione cercando vulnerabilità di sicurezza come SQL injection, XSS, autenticazione debole.","C. JMeter","D. Cucumber"], a:1, e:"DAST (Dynamic Application Security Testing) testa l'applicazione dall'esterno, come un attaccante. Tool come OWASP ZAP (gratuito) o Burp Suite Pro inviano richieste HTTP malformate per scoprire: SQL Injection, Cross-Site Scripting (XSS), broken authentication, esposizione di dati sensibili.", c:"6.1.1 Strumenti"},
{q:"Quale tipo di strumento supporta il testing dell'accessibilità web (Accessibility Testing)?", o:["A. Strumenti come Axe, WAVE o Lighthouse che analizzano automaticamente le pagine web verificando la conformità agli standard WCAG, identificando problemi come mancanza di alt text, contrasto insufficiente o form non accessibili.","B. Selenium WebDriver.","C. JMeter.","D. SonarQube."], a:0, e:"Tool di accessibility testing come Axe (integrato in Chrome DevTools), WAVE (web extension) e Lighthouse (Google, integrato in Chrome) automatizzano la verifica WCAG. Trovano rapidamente problemi comuni su grandi siti, ma non sostituiscono test con utenti reali con disabilità.", c:"6.1.1 Strumenti"},
{q:"Qual è il ruolo di un tool di SAST (Static Application Security Testing) come SonarQube?", o:["A. Eseguire test di carico sul sistema.","B. Analizzare il codice sorgente (staticamente, senza eseguirlo) per trovare vulnerabilità di sicurezza, violazioni di coding standard e codice problematico prima che il software venga compilato o eseguito.","C. Registrare e riprodurre sessioni utente.","D. Monitorare il sistema in produzione."], a:1, e:"SAST analizza il codice sorgente cercando pattern noti di vulnerabilità (es. hardcoded password, uso di funzioni deprecate e pericolose, injection flaws). È integrato nella pipeline CI/CD per dare feedback immediato agli sviluppatori. Complementare a DAST (che testa il sistema in esecuzione).", c:"6.1.2 Vantaggi"},
{q:"Cosa si intende per 'Test Harness' nel contesto dell'automazione dei test di componente?", o:["A. Un documento di pianificazione del test.","B. Un insieme di componenti software (driver e stub) che permettono di eseguire un componente in isolamento sostituendo i suoi collaboratori reali con simulacri controllati.","C. Un framework di test di performance.","D. Un tool di gestione dei difetti."], a:1, e:"Il Test Harness include: Driver (simula il chiamante del componente, fornendo input e raccogliendo output) e Stub (simula le dipendenze chiamate dal componente, restituendo valori predefiniti). Permette di testare un componente in isolamento senza che le sue dipendenze siano pronte.", c:"6.1.1 Strumenti"},
{q:"Quale approccio aiuta a evitare che l'automazione dei test diventi un 'maintenance nightmare' (incubo di manutenzione)?", o:["A. Non fare mai manutenzione degli script di test.","B. Progettare gli script con pattern riutilizzabili (es. Page Object Model per i test UI), separarli dai dati di test (data-driven testing), e aggiornarli tempestivamente quando la UI o le API cambiano.","C. Riscrivere tutto da zero ogni volta che il software cambia.","D. Usare solo test manuali per evitare la manutenzione."], a:1, e:"Il Page Object Model (POM) separa la logica di navigazione UI dalla logica di test: se la UI cambia, si aggiorna solo l'oggetto pagina, non tutti gli script. Il data-driven testing separa i dati dagli script. Queste pratiche riducono drasticamente il costo di manutenzione degli script di test automatici.", c:"6.2 Rischi e Benefici"},
{q:"Perché è importante eseguire un 'Proof of Concept' (PoC) prima di adottare un nuovo framework di automazione?", o:["A. Per usare il tool gratuitamente prima di acquistarlo.","B. Per verificare concretamente che il tool si integri con la tecnologia dell'applicazione da testare, che il team abbia le competenze necessarie (o possa acquisirle), e che i benefici attesi siano realisticamente raggiungibili nel contesto specifico.","C. È obbligatorio per legge.","D. Per trovare difetti nel framework di automazione."], a:1, e:"Un PoC (o Progetto Pilota) testa le assunzioni prima dell'investimento completo: supporta l'app target (tecnologia, protocolli)? Il team riesce ad usarlo? Si integra con la CI/CD? Costa quanto previsto (licenze, formazione)? Evita investimenti costosi in soluzioni inadatte.", c:"6.3 Introduzione di uno strumento"}

];

